  { key: 'skill_evolve', title: '鍏佽浠庣粡楠屼腑鍒涘缓鍜岀鐞嗘妧鑳?, caption: '鎻愮ず鐢ㄦ埛灏嗘湁鏁堝伐浣滄祦淇濆瓨涓?Skill銆? },
  { key: 'evolution_metrics_enabled', title: '杩涘寲鎸囨爣', caption: '璁板綍宸ュ叿鏁堟灉銆佹绱㈣川閲忋€佸弽棣堢瓑銆? },
  { key: 'evolution_suggestions_enabled', title: '杩涘寲寤鸿', caption: '鍩轰簬鎸囨爣鐢熸垚鏀硅繘寤鸿銆? },
];

function formatPercent(v: number | undefined): string {
  if (v === undefined || v === null) return '鈥?;
  return (v * 100).toFixed(1) + '%';
}

function formatDate(iso: string): string {
  if (!iso) return '';
  try {
    return new Date(iso).toLocaleDateString();
  } catch {
    return iso;
  }
}

function suggestionTypeColor(type: string): string {
  switch (type) {
    case 'persona':
      return 'purple';
    case 'prompt':
      return 'blue';
    case 'skill':
      return 'teal';
    default:
      return 'grey';
  }
}

function suggestionStatusLabel(status: string): string {
  switch (status) {
    case 'applied':
      return '宸插簲鐢?;
    case 'rejected':
      return '宸叉嫆缁?;
    case 'pending':
      return '寰呭鐞?;
    default:
      return status;
  }
}
