<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import { useQuasar } from 'quasar';
import { formatJsonText, highlightJsonHtml } from '../../utils/jsonFormat';

const props = withDefaults(
  defineProps<{
    text?: string;
    scrollHeight?: string;
    showToolbar?: boolean;
  }>(),
  {
    text: '',
    scrollHeight: '320px',
    showToolbar: true,
  },
);

const $q = useQuasar();
const displayText = ref('');
const parseError = ref('');

watch(
  () => props.text,
  (value) => {
    displayText.value = formatJsonText(value || '');
    parseError.value = '';
  },
  { immediate: true },
);

const highlightedHtml = computed(() => highlightJsonHtml(displayText.value));

function formatInPlace() {
  const next = formatJsonText(displayText.value);
  if (next === displayText.value && displayText.value.trim()) {
    try {
      JSON.parse(displayText.value);
    } catch (e) {
      parseError.value = e instanceof Error ? e.message : 'JSON 鏍煎紡閿欒';
      return;
    }
  }
  displayText.value = next;
  parseError.value = '';
}

async function copyText() {
  try {
    await navigator.clipboard.writeText(displayText.value);
    $q.notify({ type: 'positive', message: '宸插鍒?, timeout: 1200 });
  } catch {
    $q.notify({ type: 'warning', message: '澶嶅埗澶辫触' });
  }
}
</script>

