import { describe, expect, it, vi, beforeEach } from 'vitest';
import { setActivePinia, createPinia } from 'pinia';
import { mergeSessionMessages } from '../mergeSessionMessages';
import { createPlaceholderMessage } from '../streamHandlers';
import type { Message } from '../types';

describe('chat send 鈫?delta 鈫?completion 鈫?merge flow', () => {
  beforeEach(() => {
    setActivePinia(createPinia());
  });

  it('merges streaming ws row with server persistence after completion', () => {
    const sessionId = 'sess-1';
    const streamId = `ws-stream-${sessionId}`;
    const pendingId = 'pending-user-abc';

    let local: Message[] = [
      createPlaceholderMessage(pendingId, sessionId, 'user', 'hi'),
      { ...createPlaceholderMessage(streamId, sessionId, 'assistant', 'partial'), status: 'streaming' },
    ];

    local = mergeSessionMessages([], local);
    expect(local.some((m) => m.id === streamId)).toBe(true);

    local = local.map((m) => (m.id === streamId ? { ...m, content_markdown: 'Hello world', status: 'ok' } : m));

    const server: Message[] = [
      {
        ...createPlaceholderMessage('db-user-1', sessionId, 'user', 'hi'),
        id: 'db-user-1',
        status: 'ok',
      },
      {
        ...createPlaceholderMessage('db-asst-1', sessionId, 'assistant', 'Hello world'),
        id: 'db-asst-1',
        status: 'ok',
      },
    ];

    const merged = mergeSessionMessages(
      server,
      local.filter((m) => !m.id.startsWith('pending-user-')),
    );
    expect(merged.some((m) => m.id === 'ws-stream-sess-1')).toBe(true);

    const afterPersist = mergeSessionMessages(server, []);
    expect(afterPersist.map((m) => m.id)).toEqual(['db-user-1', 'db-asst-1']);
    expect(afterPersist.find((m) => m.id === 'db-asst-1')?.content_markdown).toBe('Hello world');
  });
});

import { describe, expect, it, vi } from 'vitest';
import { EnvelopeDispatcher } from '../dispatcher';
import type { Envelope } from '../envelope';
import { bindStreamHandlers, patchStreamingEnvelope } from '../streamHandlers';
import type { Message } from '../types';

function env(partial: Partial<Envelope> & { type: Envelope['type'] }): Envelope {
  return {
    id: 'e1',
    author: 'test',
    session_id: 'sess-1',
    timestamp: '',
    version: 1,
    ...partial,
  };
}

describe('bindStreamHandlers', () => {
  it('patches text_delta then text_done and completes with reload', async () => {
    const rows: Record<string, Message[]> = { 'sess-1': [] };
    const markSendingDone = vi.fn();
    const onReloadAfterCompletion = vi.fn().mockResolvedValue(undefined);
    const dispatcher = new EnvelopeDispatcher();

    const stream = {
      onType: (type: string | string[], handler: (e: Envelope) => void) =>
        dispatcher.onType(type as Envelope['type'] | Envelope['type'][], handler),
    };

    bindStreamHandlers(stream as any, {
      sessionId: 'sess-1',
      resolveActiveSessionId: () => 'sess-1',
      getMessages: (sid) => rows[sid] ?? [],
      setMessages: (sid, next) => {
        rows[sid] = next;
      },
      markSendingDone,
      onRunStatus: vi.fn(),
      onErrorNotify: vi.fn(),
      onReloadAfterCompletion,
      setLastIntentPass: vi.fn(),
    });

    dispatcher.dispatch(
      env({
        type: 'text_delta',
        content: { text: 'Hello', reasoning: '', is_partial: true },
      }),
    );
    expect(rows['sess-1']!.some((m) => m.id === 'ws-stream-sess-1')).toBe(true);
    expect(rows['sess-1']!.find((m) => m.id === 'ws-stream-sess-1')?.content_markdown).toBe('Hello');

    dispatcher.dispatch(
      env({
        type: 'text_done',
        content: { text: 'Hello world', reasoning: '', is_partial: false },
      }),
    );
    expect(rows['sess-1']!.find((m) => m.id === 'ws-stream-sess-1')?.status).toBe('ok');

    dispatcher.dispatch(env({ type: 'runner_completion' }));
    expect(markSendingDone).toHaveBeenCalled();
    expect(onReloadAfterCompletion).toHaveBeenCalledWith('sess-1');
  });

  it('skips channel-owned stream and reload on session WS', () => {
    const rows: Record<string, Message[]> = { 'sess-1': [] };
    const markSendingDone = vi.fn();
    const onReloadAfterCompletion = vi.fn().mockResolvedValue(undefined);
    const dispatcher = new EnvelopeDispatcher();
    const stream = {
      onType: (type: string | string[], handler: (e: Envelope) => void) =>
        dispatcher.onType(type as Envelope['type'] | Envelope['type'][], handler),
    };

    bindStreamHandlers(stream as any, {
      sessionId: 'sess-1',
      resolveActiveSessionId: () => 'sess-1',
      getMessages: (sid) => rows[sid] ?? [],
      setMessages: (sid, next) => {
        rows[sid] = next;
      },
      markSendingDone,
      onRunStatus: vi.fn(),
      onErrorNotify: vi.fn(),
      onReloadAfterCompletion,
      setLastIntentPass: vi.fn(),
    });

    dispatcher.dispatch(
      env({
        type: 'text_delta',
        source: 'channel',
        content: { text: 'skip', reasoning: '', is_partial: true },
      }),
    );
    expect(rows['sess-1']).toEqual([]);

    dispatcher.dispatch(env({ type: 'runner_completion', source: 'channel' }));
    expect(markSendingDone).toHaveBeenCalled();
    expect(onReloadAfterCompletion).not.toHaveBeenCalled();
  });

  it('ignores deltas for inactive session', () => {
    const rows: Record<string, Message[]> = { 'sess-1': [] };
    const dispatcher = new EnvelopeDispatcher();
    const stream = {
      onType: (type: string | string[], handler: (e: Envelope) => void) =>
        dispatcher.onType(type as Envelope['type'] | Envelope['type'][], handler),
    };

    bindStreamHandlers(stream as any, {
      sessionId: 'sess-1',
      resolveActiveSessionId: () => 'sess-2',
      getMessages: (sid) => rows[sid] ?? [],
      setMessages: (sid, next) => {
        rows[sid] = next;
      },
      markSendingDone: vi.fn(),
      onRunStatus: vi.fn(),
      onErrorNotify: vi.fn(),
      onReloadAfterCompletion: vi.fn(),
      setLastIntentPass: vi.fn(),
    });

    dispatcher.dispatch(
      env({
        type: 'text_delta',
        content: { text: 'skip', reasoning: '', is_partial: true },
      }),
    );
    expect(rows['sess-1']).toEqual([]);
  });

  it('marks pending user failed and reloads on stream error', async () => {
    const pending = {
      id: 'pending-user-1',
      session_id: 'sess-1',
      parent_message_id: '',
      turn_id: '',
      turn_number: 1,
      seq_in_turn: 0,
      role: 'user',
      content_markdown: 'hello',
      model_name: 'mock',
      token_in: 0,
      token_out: 0,
      latency_ms: 0,
      status: 'ok',
      attachments_count: 0,
      options_json: '',
      error_message: '',
      created_at: '',
    } satisfies Message;
    const rows: Record<string, Message[]> = { 'sess-1': [pending] };
    const onReloadAfterCompletion = vi.fn().mockResolvedValue(undefined);
    const dispatcher = new EnvelopeDispatcher();
    const stream = {
      onType: (type: string | string[], handler: (e: Envelope) => void) =>
        dispatcher.onType(type as Envelope['type'] | Envelope['type'][], handler),
    };

    bindStreamHandlers(stream as any, {
      sessionId: 'sess-1',
      resolveActiveSessionId: () => 'sess-1',
      getMessages: (sid) => rows[sid] ?? [],
      setMessages: (sid, next) => {
        rows[sid] = next;
      },
      markSendingDone: vi.fn(),
      onRunStatus: vi.fn(),
      onErrorNotify: vi.fn(),
      onReloadAfterCompletion,
