import { ref } from 'vue';
import { useQuasar } from 'quasar';
import { useRouter } from 'vue-router';
import type { GraphDefinition, GraphVersionInfo } from './types';
import { useGraphStore } from '../../stores/graph';

export function useGraphEditorAssets(graphDef: GraphDefinition, isNew: () => boolean) {
  const $q = useQuasar();
  const router = useRouter();
  const graphStore = useGraphStore();

  const versionDialogOpen = ref(false);
  const versions = ref<GraphVersionInfo[]>([]);
  const versionsLoading = ref(false);
  const rollingBackVersion = ref<number | null>(null);
  const templateDialogOpen = ref(false);
  const templateName = ref('');
  const templateCategory = ref('custom');
  const templateSaving = ref(false);
  const importInputRef = ref<HTMLInputElement | null>(null);

  async function openVersionDialog() {
    if (!graphDef.id) {
      $q.notify({ type: 'warning', message: '璇峰厛淇濆瓨 Graph' });
      return;
    }
    versionDialogOpen.value = true;
    versionsLoading.value = true;
    try {
      versions.value = await graphStore.fetchGraphVersions(graphDef.id);
    } catch (err) {
      $q.notify({ type: 'negative', message: err instanceof Error ? err.message : '鍔犺浇鐗堟湰澶辫触' });
    } finally {
      versionsLoading.value = false;
    }
  }

  async function rollbackVersion(version: number, onRestored?: () => Promise<void>) {
    if (!graphDef.id) return;
    rollingBackVersion.value = version;
    try {
      const restored = await graphStore.rollbackGraph(graphDef.id, version);
      Object.assign(graphDef, restored);
      versionDialogOpen.value = false;
      $q.notify({ type: 'positive', message: `宸插洖婊氬埌 v${version}` });
      await onRestored?.();
    } catch (err) {
      $q.notify({ type: 'negative', message: err instanceof Error ? err.message : '鍥炴粴澶辫触' });
    } finally {
      rollingBackVersion.value = null;
    }
  }

  async function exportCurrentGraph() {
    if (!graphDef.id) {
      $q.notify({ type: 'warning', message: '璇峰厛淇濆瓨 Graph' });
      return;
    }
    try {
      const result = await graphStore.exportGraphDefinition(graphDef.id);
      const blob = new Blob([result.json], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const anchor = document.createElement('a');
      anchor.href = url;
      anchor.download = `${graphDef.name || graphDef.id}.graph.json`;
      anchor.click();
      URL.revokeObjectURL(url);
      $q.notify({ type: 'positive', message: 'Graph 宸插鍑? });
    } catch (err) {
      $q.notify({ type: 'negative', message: err instanceof Error ? err.message : '瀵煎嚭澶辫触' });
    }
  }

  function triggerImport() {
    importInputRef.value?.click();
  }

  async function onImportFile(event: Event) {
    const input = event.target as HTMLInputElement;
    const file = input.files?.[0];
    input.value = '';
    if (!file) return;
    try {
      const json = await file.text();
      const created = await graphStore.importGraphDefinition(
        json,
        graphDef.name || file.name.replace(/\.json$/i, ''),
        graphDef.description,
      );
      Object.assign(graphDef, created);
      $q.notify({ type: 'positive', message: 'Graph 宸插鍏? });
      router.replace({ name: 'graph-editor', params: { id: created.id } });
    } catch (err) {
      $q.notify({ type: 'negative', message: err instanceof Error ? err.message : '瀵煎叆澶辫触' });
    }
  }

  function openTemplateDialog() {
    if (!graphDef.id) {
      $q.notify({ type: 'warning', message: '璇峰厛淇濆瓨 Graph' });
      return;
    }
    templateName.value = graphDef.name ? `${graphDef.name} 妯℃澘` : '';
    templateCategory.value = 'custom';
    templateDialogOpen.value = true;
  }

  async function saveTemplate() {
    if (!graphDef.id || !templateName.value.trim()) return;
    templateSaving.value = true;
    try {
      await graphStore.saveAsTemplate(
        graphDef.id,
        templateName.value.trim(),
        templateCategory.value,
        graphDef.description,
      );
      templateDialogOpen.value = false;
      $q.notify({ type: 'positive', message: '宸蹭繚瀛樹负鐢ㄦ埛妯℃澘' });
    } catch (err) {
      $q.notify({ type: 'negative', message: err instanceof Error ? err.message : '淇濆瓨妯℃澘澶辫触' });
    } finally {
      templateSaving.value = false;
    }
  }

  return {
    versionDialogOpen,
    versions,
    versionsLoading,
    rollingBackVersion,
    templateDialogOpen,
    templateName,
    templateCategory,
    templateSaving,
    importInputRef,
    openVersionDialog,
    rollbackVersion,
    exportCurrentGraph,
    triggerImport,
    onImportFile,
    openTemplateDialog,
    saveTemplate,
  };
}

import { computed, ref, watch } from 'vue';
import type { Ref } from 'vue';
import type { GraphDefinition, ValidationError, ValidationWarning } from './types';

export function useGraphLocalValidation(graphDef: Ref<GraphDefinition>) {
  const cycleWarnings = ref<ValidationWarning[]>([]);

  const localErrors = computed<ValidationError[]>(() => {
    const errors: ValidationError[] = [];
    const def = graphDef.value;
    const nodeIds = new Set(def.nodes.map((n) => n.id));

    cycleWarnings.value = [];

    if (def.nodes.length === 0) return errors;

    if (!def.entryPoint) {
      errors.push({ code: 'no_entry_point', nodeId: '', field: 'entryPoint', message: '缂哄皯鍏ュ彛鑺傜偣' });
    } else if (!nodeIds.has(def.entryPoint)) {
      errors.push({ code: 'no_entry_point', nodeId: def.entryPoint, field: 'entryPoint', message: '鍏ュ彛鑺傜偣涓嶅瓨鍦? });
    }

    const seen = new Map<string, number>();
    for (const n of def.nodes) {
      const prev = seen.get(n.id);
      if (prev !== undefined) {
        errors.push({ code: 'duplicate_node', nodeId: n.id, field: 'id', message: `鑺傜偣 ID 閲嶅: ${n.id}` });
      } else {
        seen.set(n.id, 1);
      }
    }

    for (const e of def.edges) {
      if (!nodeIds.has(e.from)) {
        errors.push({ code: 'edge_source_missing', nodeId: '', field: 'from', message: `杈规簮鑺傜偣涓嶅瓨鍦? ${e.from}` });
      }
      if (!nodeIds.has(e.to)) {
        errors.push({ code: 'edge_target_missing', nodeId: e.from, field: 'to', message: `杈圭洰鏍囪妭鐐逛笉瀛樺湪: ${e.to}` });
      }
    }
    for (const ce of def.conditionalEdges) {
      if (!nodeIds.has(ce.from)) {
        errors.push({
          code: 'edge_source_missing',
          nodeId: '',
          field: 'from',
          message: `鏉′欢杈规簮鑺傜偣涓嶅瓨鍦? ${ce.from}`,
        });
        continue;
      }
      const targets = Object.values(ce.pathMap ?? {});
      for (const t of targets) {
        if (!nodeIds.has(t)) {
          errors.push({
            code: 'edge_target_missing',
            nodeId: ce.from,
            field: 'pathMap',
            message: `鏉′欢杈圭洰鏍囪妭鐐逛笉瀛樺湪: ${t}`,
          });
        }
      }
    }

    if (def.entryPoint && nodeIds.has(def.entryPoint)) {
      const reachable = new Set<string>();
      const queue = [def.entryPoint];
      while (queue.length > 0) {
        const cur = queue.pop()!;
        if (reachable.has(cur)) continue;
        reachable.add(cur);
        for (const e of def.edges) {
          if (e.from === cur && !reachable.has(e.to)) queue.push(e.to);
        }
        for (const ce of def.conditionalEdges) {
          if (ce.from === cur) {
            for (const t of Object.values(ce.pathMap ?? {})) {
              if (!reachable.has(t)) queue.push(t);
            }
          }
        }
      }
      for (const n of def.nodes) {
        if (!reachable.has(n.id)) {
          errors.push({ code: 'unreachable_node', nodeId: n.id, field: '', message: `鑺傜偣涓嶅彲杈? ${n.id}` });
        }
      }
    }

    const unconditionalAdj = new Map<string, string[]>();
    const fullAdj = new Map<string, string[]>();
    for (const e of def.edges) {
      const ul = unconditionalAdj.get(e.from) ?? [];
      ul.push(e.to);
      unconditionalAdj.set(e.from, ul);
      const fl = fullAdj.get(e.from) ?? [];
      fl.push(e.to);
      fullAdj.set(e.from, fl);
    }
    for (const ce of def.conditionalEdges) {
      const fl = fullAdj.get(ce.from) ?? [];
      for (const t of Object.values(ce.pathMap ?? {})) fl.push(t);
      fullAdj.set(ce.from, fl);
    }

    const cycleVisited = new Set<string>();
    const cycleRecStack = new Set<string>();
    function hasCycleIn(adj: Map<string, string[]>, nodeId: string): boolean {
      cycleVisited.add(nodeId);
      cycleRecStack.add(nodeId);
      for (const neighbor of adj.get(nodeId) ?? []) {
        if (!cycleVisited.has(neighbor)) {
          if (hasCycleIn(adj, neighbor)) return true;
        } else if (cycleRecStack.has(neighbor)) {
          return true;
        }
      }
      cycleRecStack.delete(nodeId);
      return false;
    }

    let hasUnconditionalCycle = false;
    const uv = new Set<string>();
    for (const n of def.nodes) {
      if (!uv.has(n.id)) {
        cycleVisited.clear();
        cycleRecStack.clear();
        if (hasCycleIn(unconditionalAdj, n.id)) {
          hasUnconditionalCycle = true;
          break;
        }
        for (const v of cycleVisited) uv.add(v);
      }
    }
    if (hasUnconditionalCycle) {
      errors.push({ code: 'loop_no_exit', nodeId: '', field: '', message: '鍥句腑瀛樺湪鏃犳潯浠跺惊鐜紙姝诲惊鐜級' });
    } else {
      let hasConditionalCycle = false;
      const cv = new Set<string>();
      for (const n of def.nodes) {
        if (!cv.has(n.id)) {
          cycleVisited.clear();
          cycleRecStack.clear();
          if (hasCycleIn(fullAdj, n.id)) {
            hasConditionalCycle = true;
            break;
          }
          for (const v of cycleVisited) cv.add(v);
        }
      }
      if (hasConditionalCycle) {
        cycleWarnings.value.push({
          code: 'conditional_loop',
          nodeId: '',
          field: '',
          message: '鍥句腑瀛樺湪鏉′欢寰幆锛堣繍琛屾椂鍙兘鍥為€€锛?,
        });
      }
    }

    return errors;
  });

  const localWarnings = computed<ValidationWarning[]>(() => {
    const warnings: ValidationWarning[] = [];
    const def = graphDef.value;

    const connectedNodes = new Set<string>();
    for (const e of def.edges) {
      connectedNodes.add(e.from);
      connectedNodes.add(e.to);
    }
    for (const ce of def.conditionalEdges) {
      connectedNodes.add(ce.from);
      for (const t of Object.values(ce.pathMap ?? {})) connectedNodes.add(t);
    }
    if (def.entryPoint) connectedNodes.add(def.entryPoint);
    if (def.finishPoint) connectedNodes.add(def.finishPoint);

    for (const n of def.nodes) {
      if (!connectedNodes.has(n.id)) {
        warnings.push({ code: 'orphan_node', nodeId: n.id, field: '', message: `瀛ょ珛鑺傜偣锛堟棤杩炴帴锛? ${n.id}` });
      }
    }

    warnings.push(...cycleWarnings.value);

    return warnings;
  });

  const localValid = computed(() => localErrors.value.length === 0);

  return { localErrors, localWarnings, localValid };
}

import { ref, computed } from 'vue';
import type { GraphDefinition, NodeDef, EdgeDef, ConditionalEdgeDef, StateFieldDef } from './types';
import { writeGraphNodePosition } from './editor/graphLayout';

interface GraphCommand {
  label: string;
  undo: () => void;
  redo: () => void;
}

const MAX_UNDO_STACK = 50;

export function useGraphUndoRedo(graphDef: GraphDefinition, markDirty: () => void) {
  const undoStack = ref<GraphCommand[]>([]);
  const redoStack = ref<GraphCommand[]>([]);

  const canUndo = computed(() => undoStack.value.length > 0);
  const canRedo = computed(() => redoStack.value.length > 0);

  function execute(command: GraphCommand) {
    command.redo();
    undoStack.value.push(command);
    if (undoStack.value.length > MAX_UNDO_STACK) {
      undoStack.value.shift();
    }
    redoStack.value = [];
    markDirty();
  }

  function undo() {
    const command = undoStack.value.pop();
    if (!command) return;
    command.undo();
    redoStack.value.push(command);
    markDirty();
  }

  function redo() {
    const command = redoStack.value.pop();
    if (!command) return;
    command.redo();
    undoStack.value.push(command);
    markDirty();
  }

  function clear() {
    undoStack.value = [];
    redoStack.value = [];
  }

  function pushAddNode(node: NodeDef, index: number) {
    execute({
      label: `娣诲姞鑺傜偣 ${node.id}`,
      undo: () => {
        const idx = graphDef.nodes.findIndex((n) => n.id === node.id);
        if (idx >= 0) graphDef.nodes.splice(idx, 1);
      },
      redo: () => {
        graphDef.nodes.splice(index, 0, { ...node });
      },
    });
  }

  function pushDeleteNode(node: NodeDef, index: number, edges: EdgeDef[], condEdges: ConditionalEdgeDef[]) {
    execute({
      label: `鍒犻櫎鑺傜偣 ${node.id}`,
      undo: () => {
        graphDef.nodes.splice(index, 0, { ...node });
        graphDef.edges.push(...edges);
        graphDef.conditionalEdges.push(...condEdges);
      },
      redo: () => {
        const idx = graphDef.nodes.findIndex((n) => n.id === node.id);
        if (idx >= 0) graphDef.nodes.splice(idx, 1);
        graphDef.edges = graphDef.edges.filter((e) => e.from !== node.id && e.to !== node.id);
        graphDef.conditionalEdges = graphDef.conditionalEdges.filter(
          (e) => e.from !== node.id && !Object.values(e.pathMap ?? {}).includes(node.id),
        );
      },
    });
  }

  function pushDeleteNodes(
    deleted: { node: NodeDef; index: number; edges: EdgeDef[]; condEdges: ConditionalEdgeDef[] }[],
  ) {
    execute({
      label: `鎵归噺鍒犻櫎 ${deleted.length} 涓妭鐐筦,
      undo: () => {
        for (const item of deleted) {
          graphDef.nodes.splice(item.index, 0, { ...item.node });
          graphDef.edges.push(...item.edges);
          graphDef.conditionalEdges.push(...item.condEdges);
        }
      },
      redo: () => {
        const ids = new Set(deleted.map((d) => d.node.id));
        graphDef.nodes = graphDef.nodes.filter((n) => !ids.has(n.id));
        graphDef.edges = graphDef.edges.filter((e) => !ids.has(e.from) && !ids.has(e.to));
        graphDef.conditionalEdges = graphDef.conditionalEdges.filter(
          (e) => !ids.has(e.from) && !Object.values(e.pathMap ?? {}).some((v) => ids.has(v)),
        );
      },
    });
  }

  function pushDuplicateNode(originalId: string, newNode: NodeDef, index: number) {
    execute({
      label: `澶嶅埗鑺傜偣 ${originalId}`,
      undo: () => {
        const idx = graphDef.nodes.findIndex((n) => n.id === newNode.id);
        if (idx >= 0) graphDef.nodes.splice(idx, 1);
      },
      redo: () => {
        graphDef.nodes.splice(index, 0, { ...newNode });
      },
    });
  }

  function pushAddEdge(edge: EdgeDef) {
    execute({
      label: `娣诲姞杩炵嚎 ${edge.from}鈫?{edge.to}`,
      undo: () => {
        const idx = graphDef.edges.findIndex((e) => e.from === edge.from && e.to === edge.to);
        if (idx >= 0) graphDef.edges.splice(idx, 1);
      },
      redo: () => {
        graphDef.edges.push({ ...edge });
      },
    });
  }

  function pushDeleteEdge(edge: EdgeDef, index: number) {
    execute({
      label: `鍒犻櫎杩炵嚎 ${edge.from}鈫?{edge.to}`,
      undo: () => {
        graphDef.edges.splice(index, 0, { ...edge });
      },
      redo: () => {
        const idx = graphDef.edges.findIndex((e) => e.from === edge.from && e.to === edge.to);
        if (idx >= 0) graphDef.edges.splice(idx, 1);
      },
    });
  }

  function pushDeleteConditionalEdge(ce: ConditionalEdgeDef, ceIndex: number, label: string) {
    const oldPathMap = { ...ce.pathMap };
    execute({
      label: `鍒犻櫎鏉′欢杩炵嚎 ${ce.from}鈫?{label}`,
      undo: () => {
        if (ceIndex < graphDef.conditionalEdges.length) {
          graphDef.conditionalEdges[ceIndex].pathMap = oldPathMap;
        } else {
          graphDef.conditionalEdges.splice(ceIndex, 0, { ...ce, pathMap: oldPathMap });
        }
      },
      redo: () => {
        const newPathMap = { ...graphDef.conditionalEdges[ceIndex]?.pathMap };
        delete newPathMap[label];
        if (Object.keys(newPathMap).length === 0) {
          graphDef.conditionalEdges.splice(ceIndex, 1);
        } else {
          graphDef.conditionalEdges[ceIndex].pathMap = newPathMap;
        }
      },
    });
  }

  function pushSetProperty(nodeId: string, field: string, oldValue: unknown, newValue: unknown) {
    execute({
      label: `淇敼 ${nodeId}.${field}`,
      undo: () => {
        const node = graphDef.nodes.find((n) => n.id === nodeId);
        if (node) (node as any)[field] = oldValue;
      },
      redo: () => {
        const node = graphDef.nodes.find((n) => n.id === nodeId);
        if (node) (node as any)[field] = newValue;
      },
    });
  }

  function pushSetGraphProperty(field: string, oldValue: unknown, newValue: unknown) {
    execute({
      label: `淇敼 Graph ${field}`,
      undo: () => {
        (graphDef as any)[field] = oldValue;
      },
      redo: () => {
        (graphDef as any)[field] = newValue;
      },
    });
  }

  function pushDisconnectNode(nodeId: string, edges: EdgeDef[], condEdges: ConditionalEdgeDef[]) {
    execute({
      label: `鏂紑 ${nodeId} 杩炵嚎`,
      undo: () => {
        graphDef.edges.push(...edges);
        graphDef.conditionalEdges.push(...condEdges);
      },
      redo: () => {
        graphDef.edges = graphDef.edges.filter((e) => e.from !== nodeId && e.to !== nodeId);
        graphDef.conditionalEdges = graphDef.conditionalEdges.filter(
          (e) => e.from !== nodeId && !Object.values(e.pathMap ?? {}).includes(nodeId),
        );
      },
    });
  }

  function pushSetStateProperty(idx: number, field: string, oldValue: unknown, newValue: unknown) {
    execute({
      label: `淇敼 StateField[${idx}].${field}`,
      undo: () => {
        if (graphDef.stateFields[idx]) {
          (graphDef.stateFields[idx] as any)[field] = oldValue;
        }
      },
      redo: () => {
        if (graphDef.stateFields[idx]) {
          (graphDef.stateFields[idx] as any)[field] = newValue;
        }
      },
    });
  }

  function pushAddStateField(field: StateFieldDef, idx: number) {
    execute({
      label: `娣诲姞 StateField ${field.name || idx}`,
      undo: () => {
        const i = graphDef.stateFields.findIndex((f) => f === graphDef.stateFields[idx]);
        if (i >= 0) graphDef.stateFields.splice(i, 1);
      },
      redo: () => {
        graphDef.stateFields.splice(idx, 0, { ...field });
      },
    });
  }

  function pushRemoveStateField(field: StateFieldDef, idx: number) {
    execute({
      label: `鍒犻櫎 StateField ${field.name || idx}`,
      undo: () => {
        graphDef.stateFields.splice(idx, 0, { ...field });
      },
      redo: () => {
        if (graphDef.stateFields[idx]) {
          graphDef.stateFields.splice(idx, 1);
        }
      },
    });
  }

  function pushSetConditionalPathMap(
    ceIdx: number,
    oldPathMap: Record<string, string>,
    newPathMap: Record<string, string>,
  ) {
    execute({
      label: `淇敼鏉′欢璺敱 pathMap[${ceIdx}]`,
      undo: () => {
        if (graphDef.conditionalEdges[ceIdx]) {
          graphDef.conditionalEdges[ceIdx].pathMap = { ...oldPathMap };
        }
      },
      redo: () => {
        if (graphDef.conditionalEdges[ceIdx]) {
          graphDef.conditionalEdges[ceIdx].pathMap = { ...newPathMap };
        }
      },
    });
  }

  function pushSetCondFuncRef(ceIdx: number, oldValue: string, newValue: string) {
    execute({
      label: `淇敼鏉′欢璺敱 condFuncRef[${ceIdx}]`,
      undo: () => {
        if (graphDef.conditionalEdges[ceIdx]) {
          graphDef.conditionalEdges[ceIdx].condFuncRef = oldValue;
        }
      },
      redo: () => {
        if (graphDef.conditionalEdges[ceIdx]) {
          graphDef.conditionalEdges[ceIdx].condFuncRef = newValue;
        }
      },
    });
  }

  function pushAddConditionalEdge(ce: ConditionalEdgeDef, idx: number) {
    execute({
      label: `娣诲姞鏉′欢璺敱 ${ce.from}`,
      undo: () => {
        const i = graphDef.conditionalEdges.findIndex((e) => e === graphDef.conditionalEdges[idx]);
        if (i >= 0) graphDef.conditionalEdges.splice(i, 1);
      },
      redo: () => {
        graphDef.conditionalEdges.splice(idx, 0, { ...ce, pathMap: { ...ce.pathMap } });
      },
    });
  }

  function pushMoveNodes(
    moves: { nodeId: string; oldPos: { x: number; y: number }; newPos: { x: number; y: number } }[],
  ) {
    if (moves.length === 0) return;
    execute({
      label: moves.length === 1 ? `绉诲姩鑺傜偣 ${moves[0].nodeId}` : `绉诲姩 ${moves.length} 涓妭鐐筦,
      undo: () => {
        for (const move of moves) {
          writeGraphNodePosition(graphDef, move.nodeId, move.oldPos);
        }
      },
      redo: () => {
        for (const move of moves) {
          writeGraphNodePosition(graphDef, move.nodeId, move.newPos);
        }
      },
    });
  }

  function pushReconnectEdge(edgeIdx: number, oldFrom: string, oldTo: string, newFrom: string, newTo: string) {
    execute({
      label: `閲嶈繛杈?${oldFrom}鈫?{oldTo} 鈫?${newFrom}鈫?{newTo}`,
      undo: () => {
        if (graphDef.edges[edgeIdx]) {
          graphDef.edges[edgeIdx].from = oldFrom;
          graphDef.edges[edgeIdx].to = oldTo;
        }
      },
      redo: () => {
        if (graphDef.edges[edgeIdx]) {
          graphDef.edges[edgeIdx].from = newFrom;
          graphDef.edges[edgeIdx].to = newTo;
        }
      },
    });
  }

  return {
    canUndo,
    canRedo,
    undo,
    redo,
    clear,
    pushAddNode,
    pushDeleteNode,
    pushDeleteNodes,
    pushDuplicateNode,
    pushAddEdge,
    pushDeleteEdge,
    pushDeleteConditionalEdge,
    pushSetProperty,
    pushSetGraphProperty,
    pushDisconnectNode,
    pushSetStateProperty,
    pushAddStateField,
    pushRemoveStateField,
    pushSetConditionalPathMap,
    pushSetCondFuncRef,
    pushAddConditionalEdge,
    pushMoveNodes,
    pushReconnectEdge,
  };
}

import { kratosApi } from '../../services';
import type { Industry, Department, Position, PositionPromptResult } from './types';

const BASE = '/v1/industries';

export async function listIndustries(): Promise<{ items: Industry[]; total: number }> {
  const { data } = await kratosApi.get(`${BASE}`);
  return data;
}

export async function getIndustry(key: string): Promise<Industry> {
  const { data } = await kratosApi.get(`${BASE}/${key}`);
  return data;
}

export async function listDepartments(industryKey: string): Promise<{ items: Department[]; total: number }> {
  const { data } = await kratosApi.get(`${BASE}/${industryKey}/departments`);
  return data;
}

export async function listPositions(
  industryKey: string,
  departmentKey?: string,
): Promise<{ items: Position[]; total: number }> {
  const params: Record<string, string> = {};
  if (departmentKey) params.department_key = departmentKey;
  const { data } = await kratosApi.get(`${BASE}/${industryKey}/positions`, { params });
  return data;
}

export async function getPositionPrompt(
  industryKey: string,
  positionKey: string,
  variant?: string,
): Promise<PositionPromptResult> {
  const params: Record<string, string> = { variant: variant || 'general' };
  const { data } = await kratosApi.get(`${BASE}/${industryKey}/positions/${positionKey}/prompt`, { params });
  return {
    promptContent: data.prompt_content ?? data.promptContent ?? '',
    variant: data.variant ?? 'general',
    positionName: data.position_name ?? data.positionName ?? '',
    departmentName: data.department_name ?? data.departmentName ?? '',
    industryName: data.industry_name ?? data.industryName ?? '',
    industryDescription: data.industry_description ?? data.industryDescription ?? '',
    departmentDescription: data.department_description ?? data.departmentDescription ?? '',
    positionDescription: data.position_description ?? data.positionDescription ?? '',
    responsibilitiesJson: data.responsibilities_json ?? data.responsibilitiesJson ?? '',
    variantDescription: data.variant_description ?? data.variantDescription ?? '',
  };
}

export interface VariantInfo {
  key: string;
  label: string;
}

export async function listPositionVariants(industryKey: string, positionKey: string): Promise<VariantInfo[]> {
  const { data } = await kratosApi.get(`${BASE}/${industryKey}/positions/${positionKey}/variants`);
  return (data.variants ?? []).map((v: any) => ({
    key: v.key ?? v.Key ?? '',
    label: v.label ?? v.Label ?? v.key ?? v.Key ?? '',
  }));
}

import { ref } from 'vue';
import { listIndustries } from './api';
import type { Industry } from './types';

export function useIndustryMarket() {
  const industries = ref<Industry[]>([]);
  const loading = ref(false);
  const error = ref<string | null>(null);

  async function fetchIndustries() {
    loading.value = true;
    error.value = null;
    try {
      const result = await listIndustries();
      industries.value = result.items;
    } catch (e: any) {
      error.value = e?.message ?? 'Failed to load industries';
    } finally {
      loading.value = false;
    }
  }

  return { industries, loading, error, fetchIndustries };
}

