      caption: '鎺㈢储搴︺€佺畝娲佸害銆佽皑鎱庡害銆佸伐鍏峰亸濂藉拰妯″瀷鍋忓ソ銆?,
      state: agentStrategy.value
        ? `exploration=${formatScore(agentStrategy.value.exploration)} 路 caution=${formatScore(agentStrategy.value.caution)}`
        : '閫夋嫨 Agent 鍚庡姞杞?strategy',
      icon: 'tune',
      color: 'deep-purple',
      items: agentStrategy.value
        ? [
            `conciseness=${formatScore(agentStrategy.value.conciseness)}`,
            `delegation=${formatScore(agentStrategy.value.delegation)}`,
            `blacklist=${(agentStrategy.value.tool_blacklist || []).join(', ') || 'empty'}`,
          ]
        : [],
    },
    {
      title: 'Evolution Proposals',
      caption: '寰呭鏍哥殑鑷垜淇寤鸿鍜屽洖婊氭棩蹇椼€?,
      state: `${evolutionProposals.value.length} pending 路 ${evolutionMetrics.value?.events_total ?? evolutionEvents.value.length} events`,
      icon: 'rule',
      color: 'orange',
      items: evolutionProposals.value
        .slice(0, 5)
        .map(
          (proposal) =>
            `${proposal.target_field}: ${proposal.rationale || proposal.expected_impact || proposal.status}`,
        ),
    },
  ]);

  const settingChecklist = computed(() => [
    { label: '鍩虹 memory_* 璁剧疆', caption: 'Agent 璁剧疆椤靛凡鏈夋棫鐗堣蹇嗗惎鐢ㄣ€佺粨鏋滄暟鍜屾渶浣庡垎鏁般€?, done: true },
    { label: 'L0 涓婁笅鏂囩瓥鐣?, caption: 'Prompt snapshot / preview API 宸叉帴鍏ャ€?, done: true },
    { label: 'L1 宸ヤ綔璁板繂棰勭畻', caption: 'L1 task/field API 宸叉帴鍏ャ€?, done: true },
    {
      label: 'L3 璇箟璁板繂璁剧疆',
      caption: 'Facts / recall锛歚memory/v1` 鐢?cmd/admin SQLite锛坰essionmemory锛夋彁渚涖€?,
      done: factsEndpointReady.value,
    },
    { label: '宸╁浐 Worker 妯″瀷', caption: 'Agent 璁剧疆 鈫?璁板繂 Tab锛歚memory_worker_*` / `l0_compress_*`銆?, done: true },
    {
      label: '骞冲彴 Policy Strict / Backfill',
      caption: '璁板繂涓績 鈫?璁剧疆 Tab锛歁EMORY_POLICY_STRICT / MEMORY_EPISODE_BACKFILL_DISABLED锛圖B + env锛夈€?,
      done: true,
    },
    { label: 'L4 鍥捐氨涓庤繘鍖栬缃?, caption: 'Entities / neighborhood / evolution API 宸叉敞鍐屽苟鍦ㄦ湰椤佃鍙栥€?, done: true },
  ]);

  const scopeOptions = ['user', 'agent', 'team', 'workspace', 'global'].map((value) => ({ label: value, value }));
  const factStatusOptions = ['active', 'archived', 'disputed', 'deprecated', 'deleted'].map((value) => ({
    label: value,
    value,
  }));

  const factColumns = buildMemoryFactTableColumns(formatDate);
  const snapshotColumns = buildMemoryAssemblyTableColumns(formatDate);

  onMounted(loadAll);

  watch(selectedAgentId, async () => {
    selectedSessionId.value = null;
    await Promise.all([loadSessions(), loadEvolution(), loadCascade()]);
  });

  watch(selectedSessionId, () => {
    void loadSessionMemory();
  });

  async function loadAll() {
    error.value = '';
    try {
      await loadAgents();
      await Promise.all([loadSessions(), loadFacts(), loadEvolution(), loadCascade()]);
    } catch (err) {
      error.value = err instanceof Error ? err.message : '璁板繂涓績鍔犺浇澶辫触';
    }
  }

  async function loadAgents() {
    loadingAgents.value = true;
    try {
      agents.value = await agentsCatalog.fetchAgents({ limit: 200 });
      if (!selectedAgentId.value && agents.value.length) {
        selectedAgentId.value = agents.value[0].id;
      }
    } finally {
      loadingAgents.value = false;
    }
  }

  async function loadSessions() {
    loadingSessions.value = true;
    try {
      await sessionStore.loadSessions({ agent_id: selectedAgentId.value || undefined, limit: 30 });
      sessions.value = sessionStore.sessions;
      if (!selectedSessionId.value && sessions.value.length) {
        selectedSessionId.value = sessions.value[0].id;
      }
    } finally {
      loadingSessions.value = false;
    }
  }

  async function loadCascade() {
    const agentID = selectedAgentId.value || agents.value[0]?.id || '';
    if (!agentID) {
      return;
    }
    await memoryStore.loadCascadeProposals(agentID);
  }

  async function approveCascade(row: CascadeProposal) {
    cascadeActingId.value = row.id;
    try {
      await memoryStore.approveCascade(row.id);
      await Promise.all([loadCascade(), loadFacts(), loadEvolution()]);
    } finally {
      cascadeActingId.value = null;
    }
  }

  async function rejectCascade(row: CascadeProposal) {
    cascadeActingId.value = row.id;
    try {
      await memoryStore.rejectCascade(row.id);
      await loadCascade();
    } finally {
      cascadeActingId.value = null;
    }
  }

  async function previewCascade(row: CascadeProposal) {
    cascadePreviewProposalId.value = row.id;
    cascadePreviewOpen.value = true;
    memoryStore.clearCascadePreview();
    await memoryStore.loadCascadePreview(row.id);
  }

  async function openSagaDrawer(row: CascadeProposal) {
    cascadeSagaProposalId.value = row.id;
    cascadeSagaDrawerOpen.value = true;
    await memoryStore.loadCascadeSagaSteps(row.id);
  }

  async function retryCascade(row: CascadeProposal) {
    cascadeActingId.value = row.id;
    try {
      await memoryStore.retryCascade(row.id);
      await Promise.all([loadCascade(), loadFacts(), loadEvolution()]);
    } finally {
      cascadeActingId.value = null;
    }
  }

  async function compensateCascade(row: CascadeProposal) {
    cascadeActingId.value = row.id;
    try {
      await memoryStore.compensateCascade(row.id);
      await Promise.all([loadCascade(), loadFacts(), loadEvolution()]);
    } finally {
      cascadeActingId.value = null;
    }
  }

  async function confirmPreviewCascade(proposalId: string) {
    cascadeActingId.value = proposalId;
    try {
      await memoryStore.approveCascade(proposalId);
      cascadePreviewOpen.value = false;
      await Promise.all([loadCascade(), loadFacts(), loadEvolution()]);
    } finally {
      cascadeActingId.value = null;
    }
  }

  async function loadEvolution() {
    loadingEvolution.value = true;
    try {
      const agentID = selectedAgentId.value || agents.value[0]?.id || '';
      const bundle = await memoryStore.loadEvolutionForAgent(agentID);
      agentIdentity.value = bundle.identity;
      agentStrategy.value = bundle.strategy;
      evolutionProposals.value = bundle.proposals;
      evolutionEvents.value = bundle.events;
      evolutionMetrics.value = bundle.metrics;
    } catch {
      memoryStore.clearEntities();
      agentIdentity.value = null;
      agentStrategy.value = null;
      evolutionProposals.value = [];
      evolutionEvents.value = [];
      evolutionMetrics.value = null;
    } finally {
      loadingEvolution.value = false;
    }
  }

  async function loadFacts() {
    loadingFacts.value = true;
    try {
      const result = await memoryStore.loadFacts({
        keyword: factKeyword.value || undefined,
        scope_type: factScope.value || undefined,
        status: factStatus.value || undefined,
        limit: 50,
      });
      factsTotal.value = result.total;
      factsEndpointReady.value = true;
    } catch {
      memoryStore.clearFacts();
      factsTotal.value = 0;
      factsEndpointReady.value = false;
    } finally {
      loadingFacts.value = false;
    }
  }

  async function loadSessionMemory() {
    if (!selectedSessionId.value) {
      memoryStore.clearSnapshots();
      tasks.value = [];
      return;
    }
    await Promise.all([loadSnapshots(), loadTasks()]);
  }

  async function loadSnapshots() {
    if (!selectedSessionId.value) return;
    loadingSnapshots.value = true;
    try {
      await memoryStore.loadSnapshots(selectedSessionId.value, 20);
    } catch {
      memoryStore.clearSnapshots();
    } finally {
      loadingSnapshots.value = false;
    }
  }

  async function loadTasks() {
    if (!selectedSessionId.value) return;
    loadingTasks.value = true;
    try {
      tasks.value = await memoryStore.loadL1Tasks(selectedSessionId.value, { include_ended: true });
    } catch {
      tasks.value = [];
    } finally {
      loadingTasks.value = false;
    }
  }

  function resetFactFilters() {
    factKeyword.value = '';
    factScope.value = null;
    factStatus.value = 'active';
  }

  function openSnapshot(row: L0AssemblySnapshot) {
    selectedSnapshot.value = row;
    snapshotDrawer.value = true;
  }

  function openFact(row: MemoryFact) {
    selectedFact.value = row;
    factDrawer.value = true;
  }

  function contextRatioColor(value?: number) {
    const ratio = Math.max(0, Math.min(1, Number(value) || 0));
    if (ratio >= 0.85) return 'negative';
    if (ratio >= 0.6) return 'warning';
    return 'positive';
  }

  function formatPercent(value?: number) {
    return `${Math.round((Number(value) || 0) * 100)}%`;
  }

  function formatScore(value?: number) {
    return (Number(value) || 0).toFixed(2);
  }

  function formatDate(value?: string) {
    if (!value) return '-';
    const date = new Date(value);
    if (Number.isNaN(date.getTime())) return value;
    return date.toLocaleString('zh-CN', { month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' });
  }

  async function handleDeadLetterReplay(id: number) {
    await replayMemoryDeadLetter(id);
  }

  async function handleDeadLetterAbandon(id: number) {
    await abandonMemoryDeadLetter(id);
  }

  async function loadWorkerStatus() {
    loadingWorkerStatus.value = true;
    try {
      workerStatus.value = await getMemoryWorkerStatus();
    } catch {
      workerStatus.value = null;
    } finally {
      loadingWorkerStatus.value = false;
    }
  }

  return {
    tab,
    selectedAgentId,
    selectedSessionId,
    selectedSnapshot,
    selectedFact,
    factKeyword,
    factScope,
    factStatus,
    snapshotDrawer,
    factDrawer,
    error,
    loading,
    loadingFacts,
    loadingSessions,
    loadingSnapshots,
    loadingTasks,
    agentOptions,
    sessionRows,
    factRows,
    snapshotRows,
    taskRows,
    overviewCards,
    actionItems,
    memoryLayers,
    evolutionPanels,
    entities,
    loadingEvolution,
    cascadeProposals,
    loadingCascade,
    cascadeActingId,
    cascadePreviewOpen,
    cascadePreviewData,
    cascadePreviewProposalId,
    loadingCascadePreview,
    cascadeSagaDrawerOpen,
    cascadeSagaProposalId,
    sagaSteps,
    loadingCascadeSaga,
    settingChecklist,
    scopeOptions,
    factStatusOptions,
    factColumns,
    snapshotColumns,
    factsEndpointReady,
    loadAll,
    loadSessions,
    loadFacts,
    loadSessionMemory,
    loadCascade,
    approveCascade,
    rejectCascade,
    previewCascade,
    openSagaDrawer,
    retryCascade,
    compensateCascade,
    confirmPreviewCascade,
    resetFactFilters,
    openSnapshot,
    openFact,
    loadEvolution,
    handleDeadLetterReplay,
    handleDeadLetterAbandon,
    workerStatus,
    loadingWorkerStatus,
    loadWorkerStatus,
  };
}

import { computed, ref, watch, type ComputedRef, type Ref } from 'vue';
import { useQuasar } from 'quasar';
import type { ProviderForm } from './types';
import { errorMessage } from './providerUtils';
import type { ProviderPreset, ProviderModelPreset } from '../../config/providerPresets';
import { PROVIDER_RUNTIME_OVERLAY, runtimeProfileFor } from '../../config/providerRuntimeOverlay';
import { applyCatalogModelFields, applyCatalogProviderFields, catalogModelToCost } from '../model-catalog/applyCatalog';
// TECH-DEBT: direct API calls; move to store 鈥?issue #catalog-bypass
// useProviderCatalog 鐩存帴璋冪敤 listCatalogProviders / listCatalogModels锛孿n// 缁曡繃浜?Store 灞傘€傞暱鏈熷簲灏?catalog 鐘舵€佸拰鍔犺浇閫昏緫绉昏嚦涓撶敤 Store锛孿n// composable 鍙粍鍚?Store銆傚綋鍓嶄繚鐣欐槸鍥犱负 catalog 鏁版嵁浠呭湪鍚戝瀵硅瘽妗嗗唴浣跨敤锛孿n// 涓嶉渶瑕佽法椤甸潰鍏变韩锛屼笖閲嶆瀯娑夊強 Store 鎷嗗垎璁捐銆俓nimport { listCatalogModels, listCatalogProviders } from '../model-catalog/api';
import { ensureProviderMigrationMap } from '../model-catalog/providerMigration';
import type { CatalogModelSummary, CatalogProviderSummary } from '../../services/kratos/model_catalog/v1/index';

export function useProviderCatalog(deps: {
  providerForm: ProviderForm;
  providerAddMode: Ref<'catalog' | 'custom'>;
  providerCreateInspectFingerprint: Ref<string>;
  editingId: Ref<string>;
  dialogOpen: Ref<boolean>;
  isProviderResource: ComputedRef<boolean>;
  currentProviderPreset: ComputedRef<ProviderPreset | undefined>;
}) {
  const $q = useQuasar();

  const catalogProviderId = ref('');
  const catalogProviderSearch = ref('');
  const catalogProviders = ref<CatalogProviderSummary[]>([]);
  const catalogModels = ref<CatalogModelSummary[]>([]);
  const catalogModelFilterLocal = ref('');
  const catalogModelTotal = ref(0);
  const catalogLoading = ref(false);
  const catalogModelsLoading = ref(false);

  const catalogProviderOptions = computed(() =>
    catalogProviders.value.map((p) => ({
      label: p.name || p.id || '',
      value: p.id || '',
      caption: `${p.modelCount ?? 0} 妯″瀷 路 ${p.api || '鈥?}`,
    })),
  );

  const selectedCatalogProvider = computed(
    () => catalogProviders.value.find((p) => p.id === catalogProviderId.value) ?? null,
  );

  const catalogProviderHint = computed(() => {
    const p = selectedCatalogProvider.value;
    if (!p) return '';
    const env = (p.env ?? []).filter(Boolean);
    if (!env.length) return '';
    return `鐜鍙橀噺: ${env.join(', ')}`;
  });

  const catalogProviderDocUrl = computed(() => {
    const doc = selectedCatalogProvider.value?.doc?.trim();
    if (!doc) return '';
    if (/^https?:\/\//i.test(doc)) return doc;
    return `https://${doc}`;
  });

  const activeCatalogProviderId = computed(() => catalogProviderId.value || deps.providerForm.provider_code.trim());

  const useCatalogModelPicker = computed(
    () => deps.providerAddMode.value === 'catalog' || catalogModels.value.length > 0,
  );

  const catalogModelsHint = computed(() => {
    const code = activeCatalogProviderId.value;
    if (!code) return '';
    const name = selectedCatalogProvider.value?.name || deps.providerForm.provider_display_name.trim() || code;
    if (catalogModelsLoading.value) return `姝ｅ湪鍔犺浇 ${name} 鐨勬ā鍨嬧€;
    if (catalogModelTotal.value <= 0) {
      if (deps.providerAddMode.value === 'catalog') return `${name}锛氱洰褰曚腑鏃犳ā鍨嬶紙璇锋鏌?catalog 鍚屾锛塦;
      return '';
    }
    return `${name}锛?{catalogModelTotal.value} 涓ā鍨嬪彲閫塦;
  });

  const selectedCatalogModelLabel = computed(() => {
    const id = deps.providerForm.model_api_id.trim();
    if (!id) return '';
    const model = catalogModels.value.find((m) => m.id === id);
    return model?.name || id;
  });

  const selectedCatalogModel = computed(() => {
    const id = deps.providerForm.model_api_id.trim();
    if (!id) return undefined;
    return catalogModels.value.find((m) => m.id === id);
  });

  function mapCatalogModelsToOptions(models: CatalogModelSummary[]) {
    const q = catalogModelFilterLocal.value.trim().toLowerCase();
    let list = models;
    if (q) {
      list = list.filter((model) =>
        [model.id, model.name, model.family, model.knowledge].some((v) => (v || '').toLowerCase().includes(q)),
      );
    }
    return list.map((model) => ({
      label: model.name || model.id || '',
      value: model.id || '',
      caption: [
        model.id,
        model.contextTokens ? `${Math.round(model.contextTokens / 1000)}K ctx` : '',
        model.inputUsdPer1m ? `$${model.inputUsdPer1m}/M in` : '',
        model.status && model.status !== 'active' ? model.status : '',
      ]
        .filter(Boolean)
        .join(' 路 '),
    }));
  }

  const providerModelOptions = computed(() => {
    if (useCatalogModelPicker.value && catalogModels.value.length > 0) {
      return mapCatalogModelsToOptions(catalogModels.value);
    }
    if (deps.providerAddMode.value === 'catalog') return [];
    return (deps.currentProviderPreset.value?.models ?? []).map((model) => ({
      label: model.label,
      value: model.id,
      caption: `${model.id}${model.contextWindowK ? ` 路 ${model.contextWindowK}K ctx` : ''}`,
    }));
  });

  function catalogModelHasPricing(model: CatalogModelSummary | undefined): boolean {
    if (!model) return false;
    const cost = catalogModelToCost(model);
    return (
      cost.input_usd_per_1m > 0 ||
      cost.output_usd_per_1m > 0 ||
      cost.cache_read_usd_per_1m > 0 ||
      cost.cache_write_usd_per_1m > 0 ||
      cost.reasoning_usd_per_1m > 0
    );
  }

  const catalogPricingMissing = computed(
    () =>
      deps.isProviderResource.value &&
      deps.providerAddMode.value === 'catalog' &&
      Boolean(deps.providerForm.model_api_id.trim()) &&
      !catalogModelHasPricing(selectedCatalogModel.value),
  );

  watch(deps.dialogOpen, (open) => {
    if (open && deps.isProviderResource.value) {
      void ensureProviderMigrationMap().then(() => ensureCatalogLoaded());
    }
  });

  watch(catalogModels, (models) => {
    if (!deps.dialogOpen.value || !useCatalogModelPicker.value || !models.length) return;
    const id = deps.providerForm.model_api_id.trim();
    if (id && models.some((m) => m.id === id)) {
      applyCatalogModel(id);
    }
  });

  async function ensureCatalogLoaded(q = '') {
    catalogLoading.value = true;
    try {
      const res = await listCatalogProviders(q, 200, 0);
      catalogProviders.value = res.items;
    } catch (error) {
      $q.notify({ type: 'warning', message: errorMessage(error) || '妯″瀷鐩綍鏈姞杞斤紝璇峰厛鍦ㄧ郴缁熻缃悓姝?catalog' });
    } finally {
      catalogLoading.value = false;
    }
  }

  async function reloadCatalogProviders() {
    await ensureCatalogLoaded(catalogProviderSearch.value.trim());
  }

  function applyProviderRuntimeFields(providerId: string) {
    const rt = runtimeProfileFor(providerId);
    deps.providerForm.provider_type = rt.providerType;
    deps.providerForm.variant = rt.variant || 'openai';
  }

  async function loadCatalogModels(providerId: string, q = '', includeDeprecated = false) {
    if (!providerId) {
      catalogModels.value = [];
      catalogModelTotal.value = 0;
      return;
    }
    catalogModelsLoading.value = true;
    try {
      const res = await listCatalogModels(providerId, q, includeDeprecated, 500, 0);
      catalogModels.value = res.items;
      catalogModelTotal.value = res.total;
    } catch (error) {
      catalogModels.value = [];
      catalogModelTotal.value = 0;
      $q.notify({ type: 'warning', message: errorMessage(error) || '鍔犺浇鐩綍妯″瀷澶辫触' });
    } finally {
      catalogModelsLoading.value = false;
    }
  }

  function filterCatalogModelsLocal(val: string, update: (fn: () => void) => void) {
    catalogModelFilterLocal.value = val;
    update(() => {});
  }

  function applyCatalogModel(modelId: string) {
    const providerId = catalogProviderId.value || deps.providerForm.provider_code.trim();
    const model = catalogModels.value.find((item) => item.id === modelId);
    if (!model || !providerId) return;
    const fields = applyCatalogModelFields(providerId, model, true);
    const { reasoning_backfill, model_category, ...formFields } = fields;
    Object.assign(deps.providerForm, formFields);
    if (model_category?.length) {
      deps.providerForm.model_category = model_category;
    }
    if (reasoning_backfill !== undefined) {
      deps.providerForm.reasoning_backfill = reasoning_backfill;
    }
    deps.providerForm.catalog_source = 'models.dev';
    deps.providerForm.metadata_source = 'models.dev';
  }

  async function applyCatalogProvider(providerId: string) {
    if (!providerId) return;
    catalogProviderId.value = providerId;
    catalogModelFilterLocal.value = '';
    const summary = catalogProviders.value.find((item) => item.id === providerId);
    const fields = applyCatalogProviderFields(providerId, summary?.name || providerId, summary?.api);
    Object.assign(deps.providerForm, fields);
    applyProviderRuntimeFields(providerId);
    deps.providerForm.catalog_managed = true;
    deps.providerForm.catalog_source = 'models.dev';
    deps.providerForm.metadata_source = 'models.dev';
    deps.providerCreateInspectFingerprint.value = '';
    await loadCatalogModels(providerId, '', true);
    if (!catalogModels.value.length) {
      $q.notify({ type: 'warning', message: `${summary?.name || providerId} 鍦ㄧ洰褰曚腑鏃犲彲鐢ㄦā鍨媊 });
      deps.providerForm.model_api_id = '';
      return;
    }
    const keepModel = catalogModels.value.find((m) => m.id === deps.providerForm.model_api_id);
    const pick = keepModel ?? catalogModels.value[0];
    if (pick?.id) {
      deps.providerForm.model_api_id = pick.id;
      applyCatalogModel(pick.id);
    }
  }

  return {
    catalogProviderId,
    catalogProviderSearch,
    catalogProviders,
    catalogModels,
    catalogModelFilterLocal,
    catalogModelTotal,
    catalogLoading,
    catalogModelsLoading,
    catalogProviderOptions,
    catalogProviderHint,
    catalogProviderDocUrl,
    catalogModelsHint,
    selectedCatalogModelLabel,
    selectedCatalogModel,
    activeCatalogProviderId,
    useCatalogModelPicker,
    providerModelOptions,
    catalogPricingMissing,
    ensureCatalogLoaded,
    reloadCatalogProviders,
    loadCatalogModels,
    filterCatalogModelsLocal,
    applyCatalogProvider,
    applyCatalogModel,
    mapCatalogModelsToOptions,
    catalogModelHasPricing,
    applyProviderRuntimeFields,
  };
}

import { computed, ref } from 'vue';
import { useQuasar } from 'quasar';
import { errorMessage } from './providerUtils';
import { usePlatformStore } from '../../stores/platform';
import { findModelPreset, type ProviderModelPreset } from '../../config/providerPresets';
import type { Ref, ComputedRef } from 'vue';

export function useProviderInspect(deps: {
  providerForm: Record<string, any>;
  providerAddMode: Ref<'catalog' | 'custom'>;
  providerCreateInspectFingerprint: Ref<string>;
  providerEditIdentityAtOpen: Ref<string>;
  editingId: Ref<string>;
  isProviderResource: ComputedRef<boolean>;
  currentProviderPreset: ComputedRef<{ key?: string; authType?: string } | undefined>;
  applyModelPresetValues: (preset: ProviderModelPreset, overwrite?: boolean) => void;
  findCatalogModel: (modelId: string) => any | undefined;
  applyCatalogModel: (modelId: string) => void;
  catalogProviderId: Ref<string>;
  catalogModels: Ref<any[]>;
}) {
  const platformStore = usePlatformStore();
  const $q = useQuasar();

  const checkingModel = ref(false);

  const isLocalProviderModel = computed(() => {
    if (deps.providerForm.provider_type === 'ollama') return true;
    const raw = deps.providerForm.api_base_url.trim();
    if (!raw) return false;
    return /^(https?|wss?):\/\/(localhost|127\.0\.0\.1|\[::1\])([/:?#]|$)/i.test(raw);
  });

  const hasInspectApiKey = computed(() => {
    if (deps.providerForm.api_key.trim()) return true;
    if (deps.providerForm.secret_id.trim() && deps.providerForm.secret_key.trim()) return true;
    if (deps.providerForm.aws_region.trim()) return true;
    if (deps.editingId.value && deps.providerForm.api_key_set) return true;
    return false;
  });

  const canInspectProviderModel = computed(() => {
    if (!deps.providerForm.provider_code.trim() || !deps.providerForm.model_api_id.trim()) return false;
    if (isLocalProviderModel.value) return true;
    return hasInspectApiKey.value;
  });

  const providerIdentityChanged = computed(() => {
    if (!deps.editingId.value || !deps.isProviderResource.value) return false;
    const cur = `${deps.providerForm.provider_code.trim()}\0${deps.providerForm.model_api_id.trim()}`;
    return cur !== deps.providerEditIdentityAtOpen.value;
  });

  function providerCreateInspectFingerprintValue(): string {
    return [
      deps.providerForm.provider_code.trim(),
      deps.providerForm.model_api_id.trim(),
      deps.providerForm.api_base_url.trim(),
      deps.providerForm.api_key.trim(),
      deps.providerForm.provider_type.trim(),
      deps.providerForm.variant.trim(),
      deps.providerForm.secret_id.trim(),
      deps.providerForm.secret_key.trim(),
      deps.providerForm.aws_region.trim(),
    ].join('\0');
  }

  const canSubmitNewProviderModel = computed(() => {
    if (!deps.isProviderResource.value) return true;
    if (deps.editingId.value && !providerIdentityChanged.value) return true;
    if (isLocalProviderModel.value) return true;
    if (
      deps.catalogProviderId.value &&
      deps.providerForm.model_api_id.trim() &&
      deps.catalogModels.value.some((m) => m.id === deps.providerForm.model_api_id.trim())
    ) {
      return true;
    }
    if (
      deps.providerAddMode.value === 'catalog' &&
      deps.catalogProviderId.value &&
      deps.providerForm.catalog_managed &&
      deps.providerForm.model_api_id.trim()
    ) {
      return true;
    }
    const saved = deps.providerCreateInspectFingerprint.value;
    if (!saved) return false;
    return saved === providerCreateInspectFingerprintValue();
  });

  async function inspectCurrentProviderModel() {
    const code = deps.providerForm.provider_code.trim();
    const model = deps.providerForm.model_api_id.trim();
    if (!code || !model) {
      $q.notify({ type: 'negative', message: '璇峰厛濉啓 Provider 鍚嶇О鍜屾ā鍨婭D' });
      return;
    }
    if (!canInspectProviderModel.value) {
      $q.notify({ type: 'warning', message: '闈炴湰鍦版ā鍨嬮渶濉啓 API 瀵嗛挜鍚庢墠鑳芥鏌? });
      return;
    }
    checkingModel.value = true;
    try {
      const result = await platformStore.inspectModel({
        resource_id: deps.editingId.value,
        provider_code: code,
        provider_type: deps.providerForm.provider_type,
        model_api_id: model,
        api_base_url: deps.providerForm.api_base_url.trim(),
        api_key: deps.providerForm.api_key.trim(),
        variant: deps.providerForm.variant,
        secret_id: deps.providerForm.secret_id.trim(),
        secret_key: deps.providerForm.secret_key.trim(),
        aws_region: deps.providerForm.aws_region.trim(),
      });
      if (!result.ok) {
        if (!deps.editingId.value) {
          deps.providerCreateInspectFingerprint.value = '';
        }
        const preset = findModelPreset(deps.currentProviderPreset.value?.key || code, model);
        const catalogModel = deps.findCatalogModel(model);
        if (catalogModel && deps.catalogProviderId.value) {
          deps.applyCatalogModel(catalogModel.id || model);
          deps.providerForm.catalog_managed = true;
          if (!deps.editingId.value) {
            deps.providerCreateInspectFingerprint.value = providerCreateInspectFingerprintValue();
          }
          $q.notify({
            type: 'warning',
            message: `${result.message || '鏈幏鍙栧埌妯″瀷鍙傛暟'}锛涘凡浣跨敤 models.dev 鐩綍鍙傛暟鍥炲～`,
          });
          return;
        }
        if (preset) {
          deps.applyModelPresetValues(preset, true);
          deps.providerForm.metadata_source = `${deps.currentProviderPreset.value?.key || code}-preset`;
          deps.providerForm.raw_metadata_json = JSON.stringify({
            source: 'frontend-provider-preset',
            provider: deps.currentProviderPreset.value?.key || code,
            model,
          });
          $q.notify({ type: 'warning', message: `${result.message || '鏈幏鍙栧埌妯″瀷鍙傛暟'}锛涘凡浣跨敤鍓嶇棰勮鍙傛暟鍥炲～` });
          return;
        }
        $q.notify({ type: 'warning', message: result.message || '鏈幏鍙栧埌妯″瀷鍙傛暟锛屼篃娌℃湁鍖归厤鐨勯璁惧弬鏁? });
        return;
      }
      if (!deps.editingId.value) {
        deps.providerCreateInspectFingerprint.value = providerCreateInspectFingerprintValue();
      }
      if (deps.catalogProviderId.value && deps.providerForm.model_api_id.trim()) {
        const cm = deps.findCatalogModel(deps.providerForm.model_api_id.trim());
        if (cm && !deps.providerForm.input_price_usd_per_1m && !deps.providerForm.output_price_usd_per_1m) {
          deps.applyCatalogModel(cm.id || deps.providerForm.model_api_id.trim());
        }
      }
      if (result.enable_token_tailoring) deps.providerForm.enable_token_tailoring = true;
      if (!deps.providerForm.model_display_name.trim()) {
        deps.providerForm.model_display_name = result.model_display_name || model;
      }
      if (result.model_size_label && !deps.providerForm.model_size_label.trim()) {
        deps.providerForm.model_size_label = result.model_size_label;
      }
      if (result.raw_metadata_json && !deps.providerForm.raw_metadata_json.trim()) {
        deps.providerForm.raw_metadata_json = result.raw_metadata_json;
      }
      $q.notify({ type: 'positive', message: result.message || '宸查獙璇?Provider 杩為€氭€? });
    } catch (error) {
      if (!deps.editingId.value) {
        deps.providerCreateInspectFingerprint.value = '';
      }
      $q.notify({ type: 'negative', message: errorMessage(error) });
    } finally {
      checkingModel.value = false;
    }
  }

  return {
    checkingModel,
    isLocalProviderModel,
    hasInspectApiKey,
    canInspectProviderModel,
    providerIdentityChanged,
    canSubmitNewProviderModel,
    providerCreateInspectFingerprintValue,
    inspectCurrentProviderModel,
  };
}

import { computed, ref } from 'vue';
import {
  PROVIDER_PRESETS,
  findModelPreset,
  findProviderPreset,
  type ProviderModelPreset,
} from '../../config/providerPresets';
import type { Ref } from 'vue';

export function useProviderPresets(deps: {
  providerForm: Record<string, any>;
  applyModelPresetValues: (preset: ProviderModelPreset, overwrite?: boolean) => void;
}) {
  const providerPresetKey = ref('');

  const currentProviderPreset = computed(() =>
    findProviderPreset(providerPresetKey.value || deps.providerForm.provider_code),
  );

  const providerPresetOptions = computed(() =>
    PROVIDER_PRESETS.map((preset) => ({
      label: preset.label,
      value: preset.key,
      caption: `${preset.apiBaseUrl || '鎵嬪姩閰嶇疆'} 路 ${metadataLabel(preset.metadataApi)}`,
    })),
  );

  function applyModelPreset(modelId: string) {
    const preset = findModelPreset(providerPresetKey.value || deps.providerForm.provider_code, modelId);
    if (!preset) return;
    deps.applyModelPresetValues(preset, false);
  }

  function setCustomModelValue(value: string, done: (value: string, mode?: 'add' | 'add-unique' | 'toggle') => void) {
    done(value, 'add-unique');
    deps.providerForm.model_api_id = value;
  }

  function metadataLabel(value: string) {
    if (value === 'full') return '鍙煡璇㈠弬鏁?;
    if (value === 'partial') return '鍙獙璇佹ā鍨?;
    if (value === 'limited') return '鏈夐檺鏌ヨ';
    return '鎵嬪姩缁存姢';
  }

  return {
    providerPresetKey,
    currentProviderPreset,
    providerPresetOptions,
    applyModelPreset,
    setCustomModelValue,
    metadataLabel,
  };
}

import { computed, reactive, ref, type ComputedRef, type Ref } from 'vue';
import { useQuasar } from 'quasar';
import type { PlatformResource, PlatformResourceName, ModelCategory, CapabilityChip } from './types';
import { errorMessage, toNullableNumber, toNumber, getConfig, getCategories } from './providerUtils';
import { usePlatformStore } from '../../stores/platform';
import type { ProviderHAForm } from './types';
import {
  PROVIDER_RUNTIME_OVERLAY,
  PROVIDER_TYPE_OPTIONS,
  VARIANT_OPTIONS,
  runtimeProfileFor,
  microPer1KToUsdPer1M,
} from '../../config/providerRuntimeOverlay';
import { MODEL_CATEGORY_OPTIONS } from '../model-catalog/catalogCategories';
import { catalogProviderIdFor, ensureProviderMigrationMap } from '../model-catalog/providerMigration';
import { hasPricingConfigured } from '../usage/pricingWarning';
import { findProviderPreset, findModelPreset, type ProviderModelPreset } from '../../config/providerPresets';
import { useProviderCatalog } from './useProviderCatalog';
import { useProviderCredentials } from './useProviderCredentials';
import { useProviderInspect } from './useProviderInspect';
import { useProviderPresets } from './useProviderPresets';
