import { computed, onMounted, reactive, ref } from 'vue';
import { useQuasar } from 'quasar';
import type { PlatformResourceInput, PlatformResourceTreeNode } from './types';
import { errorMessage } from './providerUtils';
import { usePlatformStore } from '../../stores/platform';
import {
  taxonomyTreeStats,
  collectDefaultExpandedIds,
  filterTaxonomyTree,
  findTaxonomyNode,
  levelLabel,
  parseIsSystem,
  patchTaxonomyTreeNode,
  trimmedDesc,
  type TaxonomyLevel,
} from './taxonomyTreeUtils';
import { reorderTaxonomy } from './api';

const CATEGORY_RESOURCE = 'taxonomy' as const;

export function useTaxonomyPage() {
  const $q = useQuasar();
  const platformStore = usePlatformStore();

  const isDark = computed(() => $q.dark.isActive);
  const loading = ref(false);
  const saving = ref(false);
  const keyword = ref('');
  const onlyCustom = ref(false);
  const dialogOpen = ref(false);
  const editingId = ref('');
  const parentNode = ref<PlatformResourceTreeNode | null>(null);
  const tree = ref<PlatformResourceTreeNode[]>([]);
  const togglingIds = ref<Set<string>>(new Set());

  const form = reactive<PlatformResourceInput & { level: TaxonomyLevel }>({
    key: '',
    name: '',
    description: '',
    enabled: true,
    sort_order: 0,
    parent_id: '',
    level: 'industry',
    config_json: '{}',
    metadata_json: '{}',
  });

  const filteredTree = computed(() =>
    filterTaxonomyTree(
      tree.value.filter((node) => node.level === 'industry'),
      keyword.value,
      onlyCustom.value,
    ),
  );
  const stats = computed(() => taxonomyTreeStats(tree.value));
  const parentName = computed(() => parentNode.value?.name || '鏃?);

  async function loadTree(opts?: { silent?: boolean }) {
    if (!opts?.silent) loading.value = true;
    try {
      await platformStore.loadCategoryTree(CATEGORY_RESOURCE);
      tree.value = platformStore.categoryTree;
    } finally {
      if (!opts?.silent) loading.value = false;
    }
  }

  function syncTreePatch(id: string, patch: Partial<PlatformResourceTreeNode>) {
    tree.value = patchTaxonomyTreeNode(tree.value, id, patch);
    platformStore.categoryTree = tree.value;
  }

  function openCreate(level: TaxonomyLevel, parent?: PlatformResourceTreeNode) {
    const canonicalParent = parent ? (findNode(parent.id) ?? parent) : null;
    editingId.value = '';
    parentNode.value = canonicalParent;
    Object.assign(form, {
      key: '',
      name: '',
      description: '',
      enabled: true,
      sort_order: nextSortOrder(canonicalParent ?? undefined),
      parent_id: canonicalParent?.id ?? '',
      level,
      is_system: false,
      config_json: '{}',
      metadata_json: '{}',
    });
    dialogOpen.value = true;
  }

  function openEdit(node: PlatformResourceTreeNode) {
    editingId.value = node.id;
    parentNode.value = findNode(node.parent_id);
    Object.assign(form, {
      key: node.key,
      name: node.name,
      description: node.description,
      enabled: node.enabled,
      sort_order: node.sort_order,
      parent_id: node.parent_id,
      level: node.level as TaxonomyLevel,
      is_system: node.is_system,
      config_json: node.config_json || '{}',
      metadata_json: node.metadata_json || '{}',
    });
    dialogOpen.value = true;
  }

  async function saveNode() {
    const trimmedName = form.name.trim();
    if (!trimmedName) {
      $q.notify({ type: 'negative', message: '鍚嶇О蹇呭～' });
      return;
    }
    saving.value = true;
    try {
      const payload: PlatformResourceInput = {
        ...form,
        name: trimmedName,
        key: editingId.value ? form.key : buildKey(form.level, trimmedName),
        parent_id: form.parent_id || '',
        metadata_json: form.metadata_json || '{}',
      };
      if (editingId.value) {
        await platformStore.editResource(CATEGORY_RESOURCE, editingId.value, payload);
      } else {
        await platformStore.addResource(CATEGORY_RESOURCE, payload);
      }
      dialogOpen.value = false;
      await loadTree();
      $q.notify({ type: 'positive', message: '宸蹭繚瀛樺垎绫? });
    } catch (error) {
      $q.notify({ type: 'negative', message: errorMessage(error) || '淇濆瓨鍒嗙被澶辫触' });
    } finally {
      saving.value = false;
    }
  }

  async function removeNode(node: PlatformResourceTreeNode) {
    if (parseIsSystem(node)) {
      $q.notify({ type: 'warning', message: '绯荤粺棰勭疆鍒嗙被涓嶅彲鍒犻櫎' });
      return;
    }
    if ((node.children?.length ?? 0) > 0) {
      $q.notify({ type: 'warning', message: '璇峰厛鍒犻櫎鎴栬縼绉诲瓙鍒嗙被' });
      return;
    }
    return new Promise<void>((resolve) => {
      $q.dialog({
        title: '纭鍒犻櫎',
        message: `纭畾瑕佸垹闄ゅ垎绫汇€?{node.name}銆嶅悧锛熸鎿嶄綔涓嶅彲鎾ら攢銆俙,
        cancel: { label: '鍙栨秷', flat: true, rounded: true, noCaps: true },
        ok: { label: '鍒犻櫎', color: 'negative', rounded: true, unelevated: true, noCaps: true },
        persistent: true,
      })
        .onOk(async () => {
          try {
            await platformStore.removeResource(CATEGORY_RESOURCE, node.id);
            await loadTree();
            $q.notify({ type: 'positive', message: '宸插垹闄ゅ垎绫? });
          } catch (error) {
            $q.notify({ type: 'negative', message: errorMessage(error) || '鍒犻櫎鍒嗙被澶辫触' });
          } finally {
            resolve();
          }
        })
        .onCancel(() => resolve());
    });
  }

  async function toggleNodeEnabled(node: PlatformResourceTreeNode, enabled: boolean) {
    if (node.enabled === enabled || togglingIds.value.has(node.id)) return;

    const previous = node.enabled;
    togglingIds.value = new Set([...togglingIds.value, node.id]);
    syncTreePatch(node.id, { enabled });

    try {
      const updated = await platformStore.editResource(CATEGORY_RESOURCE, node.id, { enabled });
      syncTreePatch(node.id, { enabled: updated.enabled });
      $q.notify({ type: 'positive', message: enabled ? '鍒嗙被宸插惎鐢? : '鍒嗙被宸插仠鐢? });
    } catch (error) {
      syncTreePatch(node.id, { enabled: previous });
      $q.notify({ type: 'negative', message: errorMessage(error) || '鏇存柊鍒嗙被鐘舵€佸け璐? });
    } finally {
      const next = new Set(togglingIds.value);
      next.delete(node.id);
      togglingIds.value = next;
    }
  }

  function nextSortOrder(parent?: PlatformResourceTreeNode) {
    const siblings = parent ? (parent.children ?? []) : tree.value.filter((node) => node.level === 'industry');
    return siblings.length > 0 ? Math.max(...siblings.map((node) => node.sort_order || 0)) + 10 : 10;
  }

  function findNode(id: string) {
    if (!id) return null;
    return findTaxonomyNode(tree.value, id);
  }

  function buildKey(level: string, name: string) {
    const ascii = name
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-|-$/g, '');
    const parentPart = form.parent_id
      ? form.parent_id
          .replace(/[^a-z0-9]+/gi, '')
          .slice(-8)
          .toLowerCase()
      : 'root';
    const entropy = `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 7)}`;
    return `${level}-${parentPart}-${ascii || 'node'}-${entropy}`;
  }

  onMounted(loadTree);

  async function reorderNodes(ids: string[]) {
    try {
      await reorderTaxonomy(ids);
    } catch {
      $q.notify({ type: 'negative', message: '鎺掑簭淇濆瓨澶辫触' });
    }
  }

  return {
    isDark,
    loading,
    saving,
    togglingIds,
    keyword,
    onlyCustom,
    dialogOpen,
    editingId,
    parentNode,
    tree,
    form,
    filteredTree,
    stats,
    parentName,
    loadTree,
    openCreate,
    openEdit,
    saveNode,
    removeNode,
    toggleNodeEnabled,
    reorderNodes,
    levelLabel,
    trimmedDesc,
  };
}

/**
 * OrchestrationSpec v2 鈥?鍓嶇涓€绛夌被鍨嬶紙M53 搂2.2锛夈€俓n * 涓?definition_json 鍚屾瀯锛涗繚瀛樻椂缁?definitionToJSON 鍐欏洖銆俓n */
import type { TeamDefinition, TeamDefinitionMember, TeamFailurePolicy } from './types';

export type OrchestrationSpec = TeamDefinition & {
  version: 2;
  runtime_engine: 'graph' | 'native';
  linked_graph_id?: string;
  failure_policy?: TeamFailurePolicy;
  turn_timeout_sec?: number;
  first_byte_timeout_sec?: number;
};

export function toOrchestrationSpec(def: TeamDefinition): OrchestrationSpec {
  const engine = String(def.runtime_engine || 'graph').toLowerCase() === 'native' ? 'native' : 'graph';
  return {
    ...def,
    version: 2,
    runtime_engine: engine,
    turn_timeout_sec: def.timeout_seconds,
  };
}

export function fromOrchestrationSpec(spec: OrchestrationSpec): TeamDefinition {
  const { turn_timeout_sec, first_byte_timeout_sec, ...rest } = spec;
  return {
    ...rest,
    version: spec.version ?? 2,
    timeout_seconds: turn_timeout_sec ?? spec.timeout_seconds,
  };
}

export type { TeamDefinitionMember, TeamFailurePolicy };

