    return null;
  }

  function applyTemplate(template: TeamTemplateKey) {
    if (agents.value.length === 0) {
      $q.notify({ type: 'warning', message: '璇峰厛鍒涘缓鎴栧姞杞?Agent 鍚庡啀搴旂敤妯℃澘' });
      selectedTeamTemplateKey.value = null;
      return;
    }
    resetDefinition(definition);
    Object.assign(definition, definitionFromTemplate(template, agents.value));
    $q.notify({ type: 'positive', message: 'Team 妯℃澘宸插簲鐢? });
  }

  async function save() {
    const hint = validateTeamDefinition();
    if (hint) {
      $q.notify({ type: 'warning', message: hint });
      return;
    }
    saving.value = true;
    try {
      const payload = {
        team_key: form.team_key,
        display_name: form.display_name,
        status: form.status,
        app_name: form.app_name || form.team_key,
        definition_json: definitionJSON.value,
        category_industry_id: form.category_industry_id || '',
      };
      const saved = editingId.value
        ? await teamsPageStore.editTeam(editingId.value, payload)
        : await teamsPageStore.addTeam(payload);
      rows.value = editingId.value
        ? rows.value.map((row) => (row.id === saved.id ? saved : row))
        : [saved, ...rows.value];
      editorOpen.value = false;
      $q.notify({ type: 'positive', message: 'Team 宸蹭繚瀛? });
    } catch (err) {
      $q.notify({ type: 'negative', message: err instanceof Error ? err.message : '淇濆瓨澶辫触' });
    } finally {
      saving.value = false;
    }
  }

  async function duplicate(team: Team) {
    try {
      const created = await teamsPageStore.copyTeam(team.id);
      rows.value = [created, ...rows.value];
      $q.notify({ type: 'positive', message: 'Team 宸插鍒? });
    } catch (err) {
      $q.notify({ type: 'negative', message: err instanceof Error ? err.message : '澶嶅埗澶辫触' });
    }
  }

  function confirmRemove(team: Team) {
    $q.dialog({
      title: '鍒犻櫎 Team',
      message: `纭畾鍒犻櫎銆?{team.display_name}銆嶏紵姝ゆ搷浣滀笉鍙挙閿€銆俙,
      cancel: true,
      persistent: true,
    }).onOk(() => void remove(team));
  }

  async function remove(team: Team) {
    try {
      await teamsPageStore.removeTeam(team.id);
      rows.value = rows.value.filter((row) => row.id !== team.id);
      $q.notify({ type: 'info', message: 'Team 宸插垹闄? });
    } catch (err) {
      $q.notify({ type: 'negative', message: err instanceof Error ? err.message : '鍒犻櫎澶辫触' });
    }
  }

  async function copyKey(value: string) {
    await copyToClipboard(value);
    $q.notify({ type: 'positive', message: 'Team Key 宸插鍒? });
  }

  async function openRuns(team: Team) {
    selectedTeam.value = team;
    runsOpen.value = true;
    summariesByRun.value = {};
    stepsByRun.value = {};
    await loadRuns();
    openRunEvents(team.id);
  }

  function openRunTest(team: Team) {
    testTeam.value = team;
    testError.value = '';
    testReply.value = '';
    testRun.value = null;
    testOpen.value = true;
  }

  async function executeRunTest(content: string) {
    if (!testTeam.value) return;
    testLoading.value = true;
    testError.value = '';
    try {
      const result = await teamsPageStore.testTeam(testTeam.value.id, content);
      testReply.value = result.reply;
      testRun.value = result.run;
      $q.notify({ type: 'positive', message: 'Team 娴嬭瘯杩愯瀹屾垚' });
    } catch (err) {
      testError.value = err instanceof Error ? err.message : '杩愯娴嬭瘯澶辫触';
    } finally {
      testLoading.value = false;
    }
  }

  async function loadRunSummary(runID: string) {
    if (summariesByRun.value[runID] || summariesLoading.value[runID]) return;
    summariesLoading.value = { ...summariesLoading.value, [runID]: true };
    try {
      const summary = await teamsPageStore.loadRunSummary(runID);
      summariesByRun.value = { ...summariesByRun.value, [runID]: summary };
    } catch (err) {
      $q.notify({ type: 'negative', message: err instanceof Error ? err.message : '鍔犺浇姹囨€诲け璐? });
    } finally {
      summariesLoading.value = { ...summariesLoading.value, [runID]: false };
    }
  }

  function openRunObservatory(runID: string) {
    if (!selectedTeam.value) return;
    router.push({
      name: 'team-run-observatory',
      params: { teamId: selectedTeam.value.id, runId: runID },
    });
  }

  async function openTeamObservatory(team: Team) {
    try {
      const run = await findActiveTeamRun(team.id);
      if (run) {
        router.push({
          name: 'team-run-observatory',
          params: { teamId: team.id, runId: run.id },
        });
        return;
      }
      router.push({ name: 'team-orchestrate', params: { teamId: team.id } });
    } catch (err) {
      $q.notify({
        type: 'negative',
        message: err instanceof Error ? err.message : '鎵撳紑瑙傛祴鍙板け璐?,
      });
    }
  }

  async function loadRuns() {
    if (!selectedTeam.value) return;
    runsLoading.value = true;
    runsError.value = '';
    try {
      runs.value = await teamsPageStore.loadRuns(selectedTeam.value.id, 30);
    } catch (err) {
      runsError.value = err instanceof Error ? err.message : '鍔犺浇杩愯杞ㄨ抗澶辫触';
    } finally {
      runsLoading.value = false;
    }
  }

  async function loadRunSteps(runID: string) {
    if (stepsByRun.value[runID]?.length || stepsLoading.value[runID]) return;
    stepsLoading.value = { ...stepsLoading.value, [runID]: true };
    try {
      const steps = await teamsPageStore.loadRunSteps(runID);
      stepsByRun.value = { ...stepsByRun.value, [runID]: steps };
    } finally {
      stepsLoading.value = { ...stepsLoading.value, [runID]: false };
    }
  }

  function openRunEvents(teamID: string) {
    closeRunEvents();
    runEventsSource = teamsPageStore.subscribeRunEvents(
      GLOBAL_WS_SESSION_ID,
      teamID,
      (event) => {
        runEventsConnected.value = true;
        applyRunEvent(event);
      },
      () => {
        runEventsConnected.value = false;
      },
      (replaying) => {
        runEventsReplaying.value = replaying;
      },
    );
  }

  function closeRunEvents() {
    runEventsSource?.close();
    runEventsSource = null;
    runEventsConnected.value = false;
    runEventsReplaying.value = false;
  }

  function applyRunEvent(event: TeamRunEvent) {
    if (selectedTeam.value && event.team_id !== selectedTeam.value.id) return;
    if (event.run) {
      upsertRun(event.run);
    }
    if (event.step) {
      upsertRunStep(event.step);
    }
  }

  function upsertRun(run: TeamRun) {
    const index = runs.value.findIndex((item) => item.id === run.id);
    if (index >= 0) {
      runs.value = runs.value.map((item) => (item.id === run.id ? run : item));
      return;
    }
    runs.value = [run, ...runs.value].slice(0, 30);
  }

  function upsertRunStep(step: TeamRunStep) {
    const current = stepsByRun.value[step.run_id] ?? [];
    const exists = current.some((item) => item.id === step.id);
    const next = exists ? current.map((item) => (item.id === step.id ? step : item)) : [...current, step];
    next.sort((a, b) => a.sort_order - b.sort_order || a.created_at.localeCompare(b.created_at));
    stepsByRun.value = { ...stepsByRun.value, [step.run_id]: next };
  }

  // TECH-DEBT: reorder is local-only; add backend persistence API 鈥?issue #xxx
  function reorderTeams(ids: string[]) {
    const idIndex = new Map(ids.map((id, i) => [id, i]));
    rows.value = [...rows.value].sort((a, b) => {
      const ai = idIndex.get(a.id);
      const bi = idIndex.get(b.id);
      if (ai !== undefined && bi !== undefined) return ai - bi;
      if (ai !== undefined) return -1;
      if (bi !== undefined) return 1;
      return 0;
    });
  }

  return {
    isDark,
    rows,
    agents,
    loading,
    saving,
    error,
    search,
    modeFilter,
    statusFilter,
    industryFilter,
    categoryTree,
    industryOptions,
    teamIndustryGroups,
    currentPage,
    pageSize,
    totalFiltered,
    pageMax,
    editorOpen,
    selectedTeamTemplateKey,
    editingId,
    runsOpen,
    runsLoading,
    runsError,
    runEventsConnected,
    runEventsReplaying,
    selectedTeam,
    runs,
    stepsByRun,
    stepsLoading,
    summariesByRun,
    summariesLoading,
    testOpen,
    testTeam,
    testLoading,
    testError,
    testReply,
    testRun,
    form,
    definition,
    agentOptions,
    definitionJSON,
    canSave,
    filteredTeams,
    loadRows,
    openCreate,
    openEdit,
    addMember,
    removeMember,
    applyTemplate,
    save,
    duplicate,
    confirmRemove,
    copyKey,
    openRuns,
    openRunTest,
    executeRunTest,
    loadRunSummary,
    openRunObservatory,
    openTeamObservatory,
    loadRuns,
    loadRunSteps,
    reorderTeams,
  };
}

/** Lightweight JSON Schema object builder for Tool parameters/config definitions. */

export type SchemaFieldType = 'string' | 'number' | 'integer' | 'boolean';

export type SchemaFieldRow = {
  key: string;
  type: SchemaFieldType;
  title: string;
  description: string;
  required: boolean;
  enumValues: string;
};

export type JsonSchemaObject = {
  type?: string;
  properties?: Record<string, Record<string, unknown>>;
  required?: string[];
};

export function emptySchemaField(): SchemaFieldRow {
  return { key: '', type: 'string', title: '', description: '', required: false, enumValues: '' };
}

export function parseSchemaFields(schemaJson: string): SchemaFieldRow[] {
  let schema: JsonSchemaObject;
  try {
    schema = JSON.parse(schemaJson || '{}') as JsonSchemaObject;
  } catch {
    return [];
  }
  const props = schema.properties ?? {};
  const required = new Set(schema.required ?? []);
  return Object.entries(props).map(([key, def]) => {
    const row: SchemaFieldRow = {
      key,
      type: (def.type as SchemaFieldType) ?? 'string',
      title: String(def.title ?? ''),
      description: String(def.description ?? ''),
      required: required.has(key),
      enumValues: Array.isArray(def.enum) ? (def.enum as string[]).join(', ') : '',
    };
    return row;
  });
}

export function buildSchemaFromFields(rows: SchemaFieldRow[]): string {
  const properties: Record<string, Record<string, unknown>> = {};
  const required: string[] = [];
  for (const row of rows) {
    const key = row.key.trim();
    if (!key) continue;
    const def: Record<string, unknown> = { type: row.type };
    if (row.title.trim()) def.title = row.title.trim();
    if (row.description.trim()) def.description = row.description.trim();
    if (row.enumValues.trim()) {
      def.enum = row.enumValues
        .split(',')
        .map((s) => s.trim())
        .filter(Boolean);
    }
    properties[key] = def;
    if (row.required) required.push(key);
  }
  const schema: JsonSchemaObject = { type: 'object', properties };
  if (required.length) schema.required = required;
  return JSON.stringify(schema, null, 2);
}

/** Keys in config_json not declared in config_schema properties. */
export function configExtraKeys(configJson: string, schemaJson: string): string[] {
  let config: Record<string, unknown> = {};
  let schema: JsonSchemaObject = {};
  try {
    config = JSON.parse(configJson || '{}') as Record<string, unknown>;
  } catch {
    return [];
  }
  try {
    schema = JSON.parse(schemaJson || '{}') as JsonSchemaObject;
  } catch {
    return Object.keys(config);
  }
  const allowed = new Set(Object.keys(schema.properties ?? {}));
  return Object.keys(config).filter((k) => !allowed.has(k));
}

/** Shallow diff labels for default vs current config. */
export function configDiffSummary(currentJson: string, defaultJson: string): string[] {
  let current: Record<string, unknown> = {};
  let defaults: Record<string, unknown> = {};
  try {
    current = JSON.parse(currentJson || '{}') as Record<string, unknown>;
  } catch {
    return ['褰撳墠閰嶇疆 JSON 鏃犳晥'];
  }
  try {
    defaults = JSON.parse(defaultJson || '{}') as Record<string, unknown>;
  } catch {
    return ['榛樿閰嶇疆 JSON 鏃犳晥'];
  }
  const lines: string[] = [];
  const keys = new Set([...Object.keys(current), ...Object.keys(defaults)]);
  for (const k of keys) {
    const a = JSON.stringify(current[k]);
    const b = JSON.stringify(defaults[k]);
    if (a !== b) lines.push(`${k}: 榛樿 ${b ?? '鈥?} 鈫?褰撳墠 ${a ?? '鈥?}`);
  }
  return lines.length ? lines : ['涓庡嚭鍘傞粯璁や竴鑷?];
}

import type { QTableColumn, QTableProps } from 'quasar';

type RegistryColumn = NonNullable<QTableProps['columns']>[number];

/** AppRegistryTable / AppRegistryMarkupTable 缁熶竴鍒楀畾涔夌被鍨?*/
export type RegistryTableColumn<T extends Record<string, any> = Record<string, any>> = QTableColumn<T>;

/** 甯哥敤鍒楀 token锛圧egistry 鍒楄〃缁熶竴寮曠敤锛岄伩鍏嶆暎钀?width 瀛楃涓诧級 */
export const REGISTRY_COL_W = {
  name: '14%',
  nameWide: '18%',
  desc: '16%',
  status: '9%',
  time: '50px',
  timeWide: '18%',
  agent: '10%',
  session: '10%',
  category: '11%',
  stats: '20%',
  enabled: '40px',
  metric: '72px',
  narrow: '64px',
  actions: '90px',
  actionsWide: '100px',
  select: '48px',
} as const;

/**
 * Quasar QTable锛氳〃澶?th 璇?headerStyle锛宼body td 璇?style銆俓n * 鍒楀鐢卞悇椤甸潰 columns 瀹氫箟锛涙澶勪粎鍚屾 style 鈫?headerStyle銆俓n */
export function normalizeRegistryColumns(columns: QTableProps['columns']): QTableProps['columns'] {
  if (!Array.isArray(columns)) return columns;
  return columns.map((col) => {
    if (!col || typeof col !== 'object') return col;
    const entry = col as RegistryColumn;
    if (entry.headerStyle != null && entry.headerStyle !== '') return entry;
    if (typeof entry.style === 'string' && entry.style !== '') {
      return { ...entry, headerStyle: entry.style };
    }
    return entry;
  });
}

/**
 * 鍒楀 helper锛氬悓鏃跺啓鍏?style + headerStyle锛圦uasar 琛ㄥご/琛ㄤ綋鍚勮涓€澶勶級銆俓n * @param width CSS width 鍊硷紝濡?"14%" 鎴?"108px"锛涘惈 ":" 鏃惰涓哄畬鏁?CSS 鐗囨
 */
export function registryColWidth(width: string) {
  const css = width.includes(':') ? width : `width: ${width}`;
  return { style: css, headerStyle: css };
}

/**
 * 缁熶竴鍒楀畾涔夊啓娉曪細name 鈫?label 鈫?field 鈫?align 鈫?width 鈫?鍏跺畠灞炴€с€俓n */
export function registryCol<T extends Record<string, any>>(
  name: string,
  label: string,
  field: RegistryTableColumn<T>['field'],
  align: NonNullable<RegistryTableColumn<T>['align']>,
  width: string,
  extra?: Omit<RegistryTableColumn<T>, 'name' | 'label' | 'field' | 'align' | 'style' | 'headerStyle'>,
): RegistryTableColumn<T> {
  return { name, label, field, align, ...registryColWidth(width), ...extra };
}

/** 鎿嶄綔鍒?preset锛氬彸瀵归綈 + sticky 绫诲悕锛坰essions 绛夌壒娈婅〃鍙鐢級 */
export function registryColActions<T extends Record<string, any>>(
  width: string = REGISTRY_COL_W.actions,
  label = '鎿嶄綔',
  field: RegistryTableColumn<T>['field'] = 'id',
) {
  return registryCol<T>('actions', label, field, 'right', width, {
    sortable: false,
    classes: 'app-registry-col-actions',
    headerClasses: 'app-registry-col-actions',
  });
}

/** Toggle 鍒?preset锛氬眳涓?+ 鍥哄畾瀹藉害 */
export function registryColEnabled<T extends Record<string, any>>(
  label = '鍚敤',
  field: RegistryTableColumn<T>['field'] = 'enabled',
) {
  return registryCol<T>('enabled', label, field, 'center', REGISTRY_COL_W.enabled, { sortable: false });
}

export function registryFieldValue(row: Record<string, unknown>, field: RegistryTableColumn['field']): unknown {
  if (typeof field === 'function') return field(row);
  if (typeof field === 'string') return row[field];
  return '';
}

