    }
  }

  async function loadPositions(industryKey: string, departmentKey?: string) {
    loadingPositions.value = true;
    try {
      const result = await listPositions(industryKey, departmentKey);
      positions.value = result.items;
    } finally {
      loadingPositions.value = false;
    }
  }

  async function loadPositionPrompt(industryKey: string, positionKey: string, variant?: string) {
    loadingPrompt.value = true;
    try {
      promptResult.value = await getPositionPrompt(industryKey, positionKey, variant);
    } finally {
      loadingPrompt.value = false;
    }
  }

  async function loadPositionVariants(industryKey: string, positionKey: string) {
    loadingVariants.value = true;
    try {
      variantList.value = await listPositionVariants(industryKey, positionKey);
    } catch {
      variantList.value = [{ key: 'general', label: '閫氱敤' }];
    } finally {
      loadingVariants.value = false;
    }
  }

  return {
    industries,
    currentIndustry,
    departments,
    positions,
    departmentPositions,
    promptResult,
    variantList,
    error,
    loadingIndustries,
    loadingDetail,
    loadingDepartments,
    loadingPositions,
    loadingPrompt,
    loadingVariants,
    loadIndustries,
    loadIndustryDetail,
    loadDepartments,
    loadPositions,
    loadPositionPrompt,
    loadPositionVariants,
  };
});

import { defineStore } from 'pinia';
import { ref } from 'vue';
import {
  searchSessions,
  getSession,
  createSession,
  deleteSession,
  archiveSession,
  updateSession,
  listSessionTurns,
  getSessionTimeline,
  listSessionChatMessages,
  listSessionRuns,
  listSessionParticipants,
  previewSessionBatch,
  batchArchiveSessions,
  batchDeleteSessions,
  pinSession,
  restoreSession,
  unpinSession,
  exportSession,
} from '../../features/session/api';
import type {
  Session,
  SessionListResult,
  SessionRunRecord,
  SessionParticipant,
  BatchOperationResult,
  BatchPreviewResult,
  SessionBatchScope,
} from '../../features/session/types';
import { emitSessionMutation } from '../sessionSync';

export const useSessionStore = defineStore('session', () => {
  const sessions = ref<Session[]>([]);
  const activeSession = ref<Session | null>(null);
  const loading = ref(false);
  const error = ref<string | null>(null);
  const total = ref(0);
  const keyword = ref('');

  async function loadSessions(params?: { keyword?: string; agent_id?: string; limit?: number; offset?: number }) {
    loading.value = true;
    error.value = null;
    try {
      const result: SessionListResult = await searchSessions(params ?? {});
      sessions.value = result.items ?? [];
      total.value = result.total ?? sessions.value.length;
    } catch (e: any) {
      error.value = e?.message ?? String(e);
    } finally {
      loading.value = false;
    }
  }

  async function searchPage(params: {
    keyword?: string;
    owner_type?: string;
    status?: string;
    context_status?: string;
    limit?: number;
    offset?: number;
  }): Promise<SessionListResult> {
    error.value = null;
    try {
      return await searchSessions(params);
    } catch (e: any) {
      error.value = e?.message ?? String(e);
      throw e;
    }
  }

  async function fetchSession(id: string) {
    error.value = null;
    try {
      const s = await getSession(id);
      activeSession.value = s;
      return s;
    } catch (e: any) {
      error.value = e?.message ?? String(e);
      throw e;
    }
  }

  async function newSession(payload: { agent_id?: string; team_id?: string; owner_type?: string; title?: string }) {
    error.value = null;
    try {
      const s = await createSession({ ...payload, title: payload.title ?? '' });
      sessions.value.unshift(s);
      activeSession.value = s;
      emitSessionMutation({ type: 'update', id: s.id, session: s });
      return s;
    } catch (e: any) {
      error.value = e?.message ?? String(e);
      throw e;
    }
  }

  async function removeSession(id: string) {
    await deleteSession(id);
    removeSessionLocal(id);
    emitSessionMutation({ type: 'remove', id });
  }

  async function archive(id: string) {
    await archiveSession(id);
    removeSessionLocal(id);
    emitSessionMutation({ type: 'archive', id });
  }

  async function rename(id: string, title: string) {
    const updated = await updateSession(id, { title });
    updateSessionLocal(id, updated);
    emitSessionMutation({ type: 'update', id, session: updated });
    return updated;
  }

  async function setPinned(id: string, pinned: boolean) {
    const updated = pinned ? await pinSession(id) : await unpinSession(id);
    updateSessionLocal(id, updated);
    emitSessionMutation({ type: 'update', id, session: updated });
    return updated;
  }

  function setActiveSession(s: Session | null) {
    activeSession.value = s;
  }

  async function previewBatch(payload: {
    mode: 'archive' | 'delete';
    ids?: string[];
    older_than_days?: number;
    scope?: SessionBatchScope;
    include_archived?: boolean;
  }): Promise<BatchPreviewResult> {
    return previewSessionBatch(payload);
  }

  async function batchArchive(payload: {
    ids?: string[];
    older_than_days?: number;
    scope?: SessionBatchScope;
  }): Promise<BatchOperationResult> {
    const result = await batchArchiveSessions(payload);
    emitSessionMutation({ type: 'refresh' });
    return result;
  }

  async function batchDelete(payload: {
    ids?: string[];
    older_than_days?: number;
    scope?: SessionBatchScope;
    include_archived?: boolean;
  }): Promise<BatchOperationResult> {
    const result = await batchDeleteSessions(payload);
    emitSessionMutation({ type: 'refresh' });
    return result;
  }

  async function fetchTurns(sessionId: string, limit = 20, offset = 0) {
    error.value = null;
    try {
      return await listSessionTurns(sessionId, limit, offset);
    } catch (e: any) {
      error.value = e?.message ?? String(e);
      throw e;
    }
  }

  async function fetchTimeline(
    sessionId: string,
    params?: { limit?: number; offset?: number; kind_filter?: string; sort_order?: string },
  ) {
    error.value = null;
    try {
      return await getSessionTimeline(sessionId, params);
    } catch (e: any) {
      error.value = e?.message ?? String(e);
      throw e;
    }
  }

  async function fetchMessages(sessionId: string) {
    error.value = null;
    try {
      return await listSessionChatMessages(sessionId);
    } catch (e: any) {
      error.value = e?.message ?? String(e);
      throw e;
    }
  }

  function removeSessionLocal(id: string) {
    sessions.value = sessions.value.filter((s) => s.id !== id);
    if (activeSession.value?.id === id) activeSession.value = null;
  }

  function updateSessionLocal(id: string, updated: Session) {
    sessions.value = sessions.value.map((s) => (s.id === id ? updated : s));
    if (activeSession.value?.id === id) activeSession.value = updated;
  }

  async function exportSessionAction(id: string, format: 'markdown' | 'json') {
    error.value = null;
    try {
      return await exportSession(id, format);
    } catch (e: any) {
      error.value = e?.message ?? String(e);
      throw e;
    }
  }

  async function restore(id: string) {
    error.value = null;
    try {
      const result = await restoreSession(id);
      emitSessionMutation({ type: 'update', id, session: result });
      return result;
    } catch (e: any) {
      error.value = e?.message ?? String(e);
      throw e;
    }
  }

  async function fetchRuns(
    sessionId: string,
    limit = 20,
    offset = 0,
  ): Promise<{ items: SessionRunRecord[]; total: number }> {
    error.value = null;
    try {
      return await listSessionRuns(sessionId, limit, offset);
    } catch (e: any) {
      error.value = e?.message ?? String(e);
      throw e;
    }
  }

  async function fetchParticipants(sessionId: string): Promise<SessionParticipant[]> {
    error.value = null;
    try {
      return await listSessionParticipants(sessionId);
    } catch (e: any) {
      error.value = e?.message ?? String(e);
      throw e;
    }
  }

  return {
    sessions,
    activeSession,
    loading,
    error,
    total,
    keyword,
    loadSessions,
    searchPage,
    fetchSession,
    newSession,
    removeSession,
    archive,
    rename,
    setPinned,
    setActiveSession,
    previewBatch,
    batchArchive,
    batchDelete,
    fetchTurns,
    fetchTimeline,
    fetchMessages,
    restore,
    fetchRuns,
    fetchParticipants,
    removeSessionLocal,
    updateSessionLocal,
    exportSession: exportSessionAction,
  };
});

